"use client";
import { FormEvent, useEffect, useMemo, useRef, useState } from "react";
import { addDays, addMonths, differenceInCalendarDays, format, getDaysInMonth, parseISO, startOfMonth, startOfWeek } from "date-fns";
import { LayoutDashboard, CalendarDays, Target, Calculator, Table2, BookOpenText, ClipboardCheck, CircleAlert, GraduationCap, Building2, Library, ChartNoAxesCombined, CalendarCheck, Flag, UserRound, Settings, Bell, Search, Plus, ChevronRight, Clock3, Check, Moon, Sun, Menu, X, Sparkles, BookMarked, ExternalLink, SlidersHorizontal, Save, RotateCcw, Brain, CircleCheck, CircleDashed, ArrowUpRight, Play, Pause, RefreshCw } from "lucide-react";
import type { AimcatSchedule, AppData, StudyTask, TaskResourceStage, TimeFoundationTest, Topic } from "@/lib/types";
import { completionAccuracy, externalMaterialLinkProps, filterResourceOptions, searchCalendarTasks, taskStageKey, type ResourceFilters } from "@/lib/resource-flow";
import { Badge, Card, Empty, Field, Modal, Progress, SectionTitle } from "./ui";
import { AimcatTrendChart, ErrorChart, HoursChart } from "./charts";

type View = "dashboard"|"today"|"calendar"|"cat"|"quant"|"dilr"|"varc"|"mocks"|"errors"|"gmat"|"isb"|"resources"|"analytics"|"review"|"deadlines"|"profile"|"settings";

const nav: {label:string;view:View;icon:typeof Target;group?:string}[] = [
  {label:"Dashboard",view:"dashboard",icon:LayoutDashboard},{label:"Today",view:"today",icon:Target},{label:"Calendar",view:"calendar",icon:CalendarDays},
  {label:"CAT overview",view:"cat",icon:GraduationCap,group:"PREPARATION"},{label:"Quant",view:"quant",icon:Calculator},{label:"DILR",view:"dilr",icon:Table2},{label:"VARC",view:"varc",icon:BookOpenText},{label:"Mocks",view:"mocks",icon:ClipboardCheck},{label:"Error log",view:"errors",icon:CircleAlert},
  {label:"GMAT",view:"gmat",icon:Brain,group:"APPLICATION"},{label:"ISB application",view:"isb",icon:Building2},{label:"Resources",view:"resources",icon:Library},
  {label:"Analytics",view:"analytics",icon:ChartNoAxesCombined,group:"REVIEW"},{label:"Weekly review",view:"review",icon:CalendarCheck},{label:"Deadlines",view:"deadlines",icon:Flag},
  {label:"Profile",view:"profile",icon:UserRound,group:"SYSTEM"},{label:"Settings",view:"settings",icon:Settings}
];

const viewTitles: Record<View,string> = {dashboard:"Command center",today:"Tonight’s plan",calendar:"Study calendar",cat:"CAT 2026 roadmap",quant:"Quant tracker",dilr:"DILR practice",varc:"VARC practice",mocks:"Mock laboratory",errors:"Error log",gmat:"GMAT track",isb:"ISB application",resources:"Resource library",analytics:"Performance analytics",review:"Weekly review",deadlines:"Important deadlines",profile:"Admissions profile",settings:"Settings"};

export function CommandCenter({ initialData }: { initialData: AppData }) {
  const [data,setData]=useState(initialData); const [view,setView]=useState<View>("dashboard"); const [theme,setTheme]=useState(data.settings.theme||"light"); const [sidebar,setSidebar]=useState(false); const [modal,setModal]=useState<string|null>(null); const [busy,setBusy]=useState(false); const [toast,setToast]=useState(""); const [date,setDate]=useState(data.meta.today); const [startFocus,setStartFocus]=useState(false); const [highlightTask,setHighlightTask]=useState<number|null>(null);
  async function action(name:string,payload:Record<string,unknown>,message="Saved") { setBusy(true); const response=await fetch("/api/app",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:name,payload})}); if(!response.ok){const e=await response.json();setToast(e.detail||e.error||"Could not save");setBusy(false);throw new Error(e.detail||"Could not save");} const updated=await fetch(`/api/app?date=${date}`).then(r=>r.json()); setData(updated);setBusy(false);setModal(null);setToast(message);setTimeout(()=>setToast(""),2600); }
  async function changeDate(next:string){setDate(next);setBusy(true);const updated=await fetch(`/api/app?date=${next}`).then(r=>r.json());setData(updated);setBusy(false);}
  function navigate(next:View){setView(next);setSidebar(false);}
  return <div className={`app ${theme}`}>
    <aside className={`sidebar ${sidebar?"open":""}`}><div className="brand"><div className="brand-mark">N</div><div><strong>Northstar</strong><span>MBA PREP OS</span></div><button className="mobile-close" onClick={()=>setSidebar(false)}><X/></button></div><nav>{nav.map((item,i)=>{const prev=nav[i-1];return <div key={item.view}>{item.group&&item.group!==prev?.group&&<div className="nav-group">{item.group}</div>}<button className={view===item.view?"active":""} onClick={()=>navigate(item.view)}><item.icon size={18}/><span>{item.label}</span>{item.view==="today"&&<em>{data.tasks.filter(t=>t.date===date&&!t.completed).length}</em>}</button></div>})}</nav><div className="sidebar-goal"><div><span>CAT 2026 target</span><strong>98–99+ %ile</strong></div><Progress value={Math.max(4,100-data.meta.countdown/1.09)}/><small>{data.meta.countdown} days · {data.meta.phase}</small></div></aside>
    <main><header className="topbar"><button className="menu" onClick={()=>setSidebar(true)}><Menu/></button><div><span className="breadcrumb">MBA PREP / {viewTitles[view].toUpperCase()}</span><h1>{viewTitles[view]}</h1></div><div className="top-actions"><button className="icon-btn" title="Notifications" onClick={()=>setView("deadlines")}><Bell size={19}/><i/></button><button className="icon-btn" title="Toggle theme" onClick={()=>{const t=theme==="light"?"dark":"light";setTheme(t);action("settings",{theme:t},"Theme saved")}}>{theme==="light"?<Moon size={19}/>:<Sun size={19}/>}</button><div className="avatar">AJ</div></div></header>
      <div className="page">{view==="dashboard"&&<Dashboard data={data} nav={navigate} action={action} start={()=>{setStartFocus(true);navigate("today")}} toggle={id=>action("toggleTask",{id,completed:!data.tasks.find(t=>t.id===id)?.completed},"Plan updated")} />}{view==="today"&&<Today data={data} date={date} changeDate={changeDate} action={action} open={setModal} startFocused={startFocus} consumeStart={()=>setStartFocus(false)} highlightTask={highlightTask}/>} {view==="calendar"&&<Calendar data={data} action={action} select={(d,taskId)=>{setHighlightTask(taskId||null);changeDate(d);setView("today")}}/>}{view==="cat"&&<CatOverview data={data}/>} {(view==="quant"||view==="dilr"||view==="varc")&&<TopicTracker subject={view==="quant"?"Quant":view.toUpperCase()} data={data} save={(p)=>action("updateTopic",p,"Topic updated")}/>} {view==="mocks"&&<Mocks data={data} action={action} open={()=>setModal("mock")}/>} {view==="errors"&&<Errors data={data} open={()=>setModal("error")}/>} {view==="gmat"&&<GMAT data={data} open={()=>setModal("mock")}/>} {view==="isb"&&<ISB data={data} open={()=>setModal("story")}/>} {view==="resources"&&<Resources data={data} action={action} open={()=>setModal("resource")}/>} {view==="analytics"&&<Analytics data={data}/>} {view==="review"&&<WeeklyReview data={data}/>} {view==="deadlines"&&<Deadlines data={data} save={p=>action("updateDeadline",p,"Deadline updated")}/>} {view==="profile"&&<Profile data={data}/>} {view==="settings"&&<SettingsPage data={data} action={action}/>}</div>
    </main>{sidebar&&<div className="sidebar-scrim" onClick={()=>setSidebar(false)}/>} {busy&&<div className="saving"><RotateCcw className="spin" size={16}/> Saving</div>} {toast&&<div className="toast"><Check size={16}/>{toast}</div>}
    {modal==="mock"&&<FormModal title="Add mock result" type="mock" close={()=>setModal(null)} submit={p=>action("addMock",p,"Mock saved — future planning can now adapt")}/>} {modal==="error"&&<FormModal title="Log a reusable lesson" type="error" close={()=>setModal(null)} submit={p=>action("addError",p,"Error lesson saved")}/>} {modal==="resource"&&<FormModal title="Add resource" type="resource" close={()=>setModal(null)} submit={p=>action("addResource",p,"Resource added")}/>} {modal==="story"&&<FormModal title="Capture achievement story" type="story" close={()=>setModal(null)} submit={p=>action("addStory",p,"Story captured")}/>} {modal==="close"&&<FormModal title="Close the day" type="close" close={()=>setModal(null)} submit={p=>action("closeDay",{...p,date},"Day closed — tomorrow will use this feedback")}/>} {modal==="task"&&<FormModal title="Add manual task" type="task" close={()=>setModal(null)} submit={p=>action("addTask",{...p,date},"Manual task added and protected")}/>} 
  </div>
}

function Dashboard({data,nav,action,start,toggle}:{data:AppData;nav:(v:View)=>void;action:Phase2Action;start:()=>void;toggle:(id:number)=>void}) {
 const today=data.tasks.filter(t=>t.date===data.meta.today);const pct=data.meta.plannedMinutes?data.meta.completedMinutes/data.meta.plannedMinutes*100:0;const latest=data.aimcatMeta.last?.result;const next=data.aimcatMeta.next;const [planning,setPlanning]=useState<AimcatSchedule|null>(null);const nextDeadline=data.deadlines.find(d=>d.date>=data.meta.today&&d.status!=="Complete");const dLeft=nextDeadline?Math.max(0,differenceInCalendarDays(parseISO(nextDeadline.date),parseISO(data.meta.today))):0;const errors=weakAreas(data);const weekStart=format(startOfWeek(parseISO(data.meta.today),{weekStartsOn:1}),"yyyy-MM-dd");const week=data.tasks.filter(t=>t.date>=weekStart&&t.date<=data.meta.today);const recent=data.aimcatTrend.slice(-3);
 return <>
  <div className="hero-row"><div><span className="date-label">{format(parseISO(data.meta.today),"EEEE, MMMM d")}</span><h2>Good evening, Anusha.</h2><p>Your plan is tuned for the <strong>{data.meta.phase}</strong> phase. Protect the AIMCAT feedback loop tonight.</p></div><button className="primary" onClick={start}>Start tonight’s plan <ChevronRight size={17}/></button></div>
  {next&&<Card className="next-aimcat"><div><span className="eyebrow">NEXT AIMCAT · PRIORITY A</span><h2>{next.test_ref}</h2><p>Available {formatWindow(next)} · planned {format(parseISO(next.planned_attempt_date||next.preferred_attempt_date),"MMM d")}</p></div><div className="aimcat-countdown"><strong>{Math.max(0,differenceInCalendarDays(parseISO(next.start_date),parseISO(data.meta.today)))}</strong><span>days until window</span></div><div className="aimcat-actions"><button className="secondary" onClick={()=>nav("calendar")}>View prep plan</button><button className="primary" onClick={()=>setPlanning(next)}>Change attempt date</button></div></Card>}
  <div className="metric-grid four"><Metric label="CAT countdown" value={String(data.meta.countdown)} suffix="days" sub="November 29, 2026" tone="blue"/><Metric label="Today’s progress" value={`${Math.floor(data.meta.completedMinutes/60)}h ${data.meta.completedMinutes%60}m`} suffix="/ 6h" sub={`${Math.round(pct)}% of planned study`} progress={pct}/><Metric label="Current CAT level" value={latest?String(latest.overall_percentile):"—"} suffix={latest?"%ile":"baseline pending"} sub={latest?`${latest.name} · ${latest.date}`:"First diagnostic — AIMCAT2714"}/><Metric label="Schedule health" value={data.meta.behind.label} sub={data.meta.behind.detail} tone={data.meta.behind.label==="On track"?"green":"amber"}/></div>
  <div className="aimcat-dashboard-grid"><Card><SectionTitle eyebrow="LAST AIMCAT" title={latest?latest.name:"First diagnostic — AIMCAT2714"}/>{latest?<div className="aimcat-score-grid">{[["Overall",latest.overall_percentile],["VARC",latest.varc_percentile],["DILR",latest.dilr_percentile],["QA",latest.qa_percentile]].map(([label,value])=><span key={label}><b>{value}</b><small>{label} %ile</small></span>)}</div>:<p className="small-note">Take AIMCAT2714 inside its Aug 15–19 window. It is diagnostic; syllabus completion is not a prerequisite.</p>}</Card><Card><SectionTitle eyebrow="ROLLING LAST 3 AIMCATS" title="Trend, not one-score overreaction"/>{recent.length?<div className="rolling-lines">{[["Overall","overall_percentile"],["VARC","varc_percentile"],["DILR","dilr_percentile"],["QA","qa_percentile"]].map(([label,key])=><div key={label}><b>{label}</b><span>{recent.map(row=>row[key as keyof typeof row]).join(" → ")}</span></div>)}</div>:<p className="small-note">Rolling signals unlock after AIMCAT results are recorded.</p>}</Card></div>
  <div className="dashboard-grid"><div className="span-8"><Card><SectionTitle eyebrow="TODAY · 6-HOUR OPERATING PLAN" title="Learn → Practice → AIMCAT → Analyse → Diagnose → Repair" action={<button className="link-btn" onClick={()=>nav("today")}>Open full plan <ArrowUpRight size={15}/></button>}/><div className="agenda">{today.map((t,i)=><AgendaItem key={t.id} task={t} last={i===today.length-1} complete={()=>nav("today")} undo={()=>toggle(t.id)} replace={()=>nav("today")}/>)}</div>{!today.length&&<Empty title="No plan for this date" text="Open Today to generate or add a manual task."/>}</Card></div>
   <div className="span-4 stack"><Card className="deadline-card"><div className="card-icon red"><Flag size={18}/></div><span className="eyebrow">NEXT DEADLINE</span><h3>{nextDeadline?.title||"No upcoming deadlines"}</h3>{nextDeadline&&<><div className="deadline-number">{dLeft}<small>days</small></div><p>{format(parseISO(nextDeadline.date),"EEEE, MMM d, yyyy")} {nextDeadline.time}</p><button className="link-btn" onClick={()=>nav("deadlines")}>View all deadlines <ChevronRight size={15}/></button></>}</Card><Card><SectionTitle eyebrow="FOCUS SIGNAL" title="Weak areas" action={<button className="link-btn" onClick={()=>nav("errors")}>Error log</button>}/><div className="weak-list">{errors.slice(0,5).map((w,i)=><div key={w.name}><span className={`rank r${i+1}`}>{i+1}</span><div><strong>{w.name}</strong><small>{w.subject} · {w.reason}</small></div><ChevronRight size={15}/></div>)}</div></Card></div>
   <div className="span-7"><Card><SectionTitle eyebrow="LAST 7 DAYS" title="Output, not just attendance"/><HoursChart tasks={week}/></Card></div><div className="span-5"><Card><SectionTitle eyebrow="THIS WEEK" title="Practice volume"/><div className="output-grid"><Output n={week.filter(t=>t.completed).reduce((s,t)=>s+(t.actual_duration||t.duration),0)/60} label="Hours"/><Output n={week.filter(t=>t.subject==="Quant"&&t.completed).reduce((s,t)=>s+t.target_count,0)} label="Questions"/><Output n={week.filter(t=>t.subject==="DILR"&&t.completed).reduce((s,t)=>s+t.target_count,0)} label="DILR sets"/><Output n={week.filter(t=>t.subject==="VARC"&&t.completed).reduce((s,_t)=>s+2,0)} label="RCs"/><Output n={week.filter(t=>t.kind==="mock"&&t.completed).length} label="AIMCATs"/><Output n={data.meta.revisionDue} label="Revisions due"/></div><div className="principle"><Sparkles size={18}/><span><strong>Tonight’s principle</strong> Ask “should I attempt this?”—not only “can I solve this?”</span></div></Card></div></div>
  {planning&&<AimcatDateModal aimcat={planning} close={()=>setPlanning(null)} save={payload=>action("planAimcat",{...payload,schedule_id:planning.id},`${planning.test_ref} replanned`).then(()=>setPlanning(null))}/>} 
 </>
}

function Metric({label,value,suffix,sub,tone="",progress}:{label:string;value:string;suffix?:string;sub:string;tone?:string;progress?:number}){return <Card className={`metric ${tone}`}><span>{label}</span><div><strong>{value}</strong>{suffix&&<em>{suffix}</em>}</div><small>{sub}</small>{progress!==undefined&&<Progress value={progress}/>}</Card>}
function Output({n,label}:{n:number;label:string}){return <div className="output"><strong>{Number.isInteger(n)?n:n.toFixed(1)}</strong><span>{label}</span></div>}
type Phase2Action = (name:string,payload:Record<string,unknown>,message?:string)=>Promise<void>;

function formatWindow(aimcat:AimcatSchedule){const start=parseISO(aimcat.start_date);const end=parseISO(aimcat.end_date);return start.getMonth()===end.getMonth()?`${format(start,"MMM d")}–${format(end,"d")}`:`${format(start,"MMM d")}–${format(end,"MMM d")}`}
function AimcatStatusBadge({status}:{status:AimcatSchedule["status"]}){const tone=status==="COMPLETED"?"green":status==="ANALYSIS_DUE"||status==="MISSED"?"red":status==="AVAILABLE"||status==="PLANNED"?"blue":"neutral";return <Badge tone={tone}>{status.replaceAll("_"," ")}</Badge>}

function AimcatDateModal({aimcat,close,save}:{aimcat:AimcatSchedule;close:()=>void;save:(payload:Record<string,unknown>)=>void}){
 const historical=Boolean(aimcat.historical&&!aimcat.converted_to_additional);const initial=historical?format(addDays(parseISO(dataTodayForAimcat(aimcat)),1),"yyyy-MM-dd"):aimcat.planned_attempt_date||aimcat.preferred_attempt_date;
 return <Modal title={historical?`Use ${aimcat.test_ref} as an additional mock`:`Plan ${aimcat.test_ref}`} onClose={close}><form className="form-grid" onSubmit={event=>{event.preventDefault();save(formObject(event))}}><div className="reschedule-summary"><CalendarDays size={19}/><div><strong>{historical?"Past AIMCAT Library":`Official window · ${formatWindow(aimcat)}`}</strong><span>{historical?"This creates an optional additional mock and does not add historical backlog.":`Recommended attempt · ${format(parseISO(aimcat.preferred_attempt_date),"EEEE, MMM d")}`}</span></div></div><Field label="Attempt date" span><input required name="date" type="date" min={historical?"2026-08-12":aimcat.start_date} max={historical?"2026-11-18":aimcat.end_date} defaultValue={initial}/></Field><p className="reschedule-preserved"><Check size={14}/>{historical?"This is a manual Priority B additional mock. Scheduled Priority A AIMCATs remain unchanged.":"Northstar will move the full six-hour lifecycle and restore normal study on the old date."}</p><FormButtons close={close}/></form></Modal>
}

function dataTodayForAimcat(aimcat:AimcatSchedule){return aimcat.end_date<"2026-08-12"?"2026-08-12":aimcat.preferred_attempt_date}

function AimcatResultModal({aimcat,close,save}:{aimcat:AimcatSchedule;close:()=>void;save:(payload:Record<string,unknown>)=>void}){
 return <Modal title={`Record ${aimcat.test_ref} result`} onClose={close} wide><form className="form-grid aimcat-result-form" onSubmit={event=>{event.preventDefault();save(formObject(event))}}><Field label="Actual attempt date"><input required name="date" type="date" min={aimcat.converted_to_additional?"2026-08-12":aimcat.start_date} max={aimcat.converted_to_additional?"2026-11-18":aimcat.end_date} defaultValue={aimcat.actual_attempt_date||aimcat.planned_attempt_date||aimcat.preferred_attempt_date}/></Field><Field label="Overall score"><input required name="overall_score" type="number" step="0.01" min="0"/></Field><Field label="Overall percentile"><input required name="overall_percentile" type="number" step="0.01" min="0" max="100"/></Field><div/><div className="aimcat-section-head"><b>Section</b><span>Score</span><span>%ile</span><span>Attempts</span><span>Correct</span><span>Incorrect</span></div>{["varc","dilr","qa"].map(section=><div className="aimcat-section-inputs" key={section}><b>{section.toUpperCase()}</b><input aria-label={`${section} score`} required name={`${section}_score`} type="number" step="0.01"/><input aria-label={`${section} percentile`} required name={`${section}_percentile`} type="number" min="0" max="100" step="0.01"/><input aria-label={`${section} attempts`} required name={`${section}_attempts`} type="number" min="0"/><input aria-label={`${section} correct`} required name={`${section}_correct`} type="number" min="0"/><input aria-label={`${section} incorrect`} required name={`${section}_incorrect`} type="number" min="0"/></div>)}<div className="taxonomy-title"><b>A–G analysis</b><span>A confident · B uncertain/lucky · C concept · D calculation/reading · E too long/selection · F easy unattempted · G correctly left</span></div><div className="taxonomy-inputs">{[["a","Correct + confident"],["b","Correct but uncertain"],["c","Conceptual error"],["d","Calculation / reading"],["e","Too long / poor selection"],["f","Easy after test"],["g","Correctly left"]].map(([key,label])=><Field label={`${key.toUpperCase()} · ${label}`} key={key}><input name={`class_${key}`} type="number" min="0" defaultValue="0"/></Field>)}</div><Field label="Easy questions missed"><input name="easy_missed" type="number" min="0" defaultValue="0"/></Field><Field label="D + E + F errors"><input name="def_errors" type="number" min="0" defaultValue="0"/></Field><Field label="Time-waste questions"><input name="time_waste_questions" type="number" min="0" defaultValue="0"/></Field><Field label="Poor DILR set selections"><input name="poor_dilr_selections" type="number" min="0" defaultValue="0"/></Field><Field label="Guessing errors"><input name="guessing_errors" type="number" min="0" defaultValue="0"/></Field><Field label="Topics involved"><input name="topics_involved" placeholder="Percentages, Arrangements, RC inference"/></Field><Field label="Top weak topics" span><input name="weak_topics" placeholder="Comma-separated topics for adaptive repair"/></Field><Field label="Strategy change for next AIMCAT" span><textarea name="strategy_next"/></Field><Field label="Notes" span><textarea name="notes"/></Field><FormButtons close={close}/></form></Modal>
}

function AgendaItem({task,last,complete,undo,replace,reschedule,checkpoint,highlighted=false}:{task:StudyTask;last:boolean;complete:()=>void;undo:()=>void;replace:(stage:TaskResourceStage)=>void;reschedule?:()=>void;checkpoint?:()=>void;highlighted?:boolean}){
 return <div id={`task-${task.id}`} className={`agenda-item ${task.completed?"done":""} ${highlighted?"highlighted":""}`}>
  <div className="agenda-time"><strong>{displayTime(task.start_time)}</strong><span>{task.duration} min</span></div>
  <div className="timeline"><i/><b className={last?"last":""}/></div>
  <button className="check" onClick={task.completed?undo:complete} aria-label={`Mark ${task.title} ${task.completed?"incomplete":"complete"}`}>{task.completed?<Check size={16}/>:null}</button>
  <div className="agenda-content">
   <div><Badge tone={subjectTone(task.subject)}>{task.subject}</Badge><Badge>{task.priority}</Badge>{task.topic_id&&<Badge tone="blue">{progressionLabel(task.difficulty)}</Badge>}{task.completed_early?<Badge tone="green">COMPLETED EARLY</Badge>:task.rescheduled?<Badge tone="purple">MOVED</Badge>:null}{task.reallocated_from_date&&<Badge tone="purple">REALLOCATED FROM {format(parseISO(task.reallocated_from_date),"MMM d")}</Badge>}{!task.completed&&reschedule&&<button type="button" className="task-move" onClick={reschedule}><CalendarDays size={13}/> Move</button>}</div>
   <h3>{task.title}</h3><p>{task.detail}</p>
   {task.adaptive_reason&&<p className="adaptive-why"><Sparkles size={13}/><span><b>Why this?</b> {task.adaptive_reason}</span></p>}
   {task.resource_stages.length>0?<div className="material-stages">{task.resource_stages.map(stage=><div className="material-stage" key={stage.assignment_id}><div className="stage-label"><b>{task.kind==="mock"&&stage.stage==="PYQ"?"FULL MOCK":stage.stage}</b><span>{stage.estimated_minutes} min</span></div><div className="stage-resource"><strong>{stage.provider} — {stage.title}</strong>{stage.target_count>0&&<small>{stage.target_count} target{stage.accuracy_target>0?` · ≥${stage.accuracy_target}% accuracy`:""}</small>}{stage.platform_path&&<small>{stage.platform_path}</small>}</div><div className="stage-actions">{stage.url?<a className="material-open" href={stage.url} {...externalMaterialLinkProps}>Open {task.kind==="mock"?"T.I.M.E. portal":"material"} <ExternalLink size={13}/></a>:<span className="platform-only">Use platform path</span>}<button type="button" onClick={()=>replace(stage)}><RefreshCw size={12}/> Replace Material</button></div></div>)}</div>:<div className="task-meta"><span><BookMarked size={14}/>{task.resource}</span>{task.target_count>0&&<span><Target size={14}/>{task.target_count} target</span>}</div>}
   {task.time_foundation_test&&<TimeCheckpointCard test={task.time_foundation_test} subject={task.subject} record={checkpoint}/>} 
   {task.result&&<div className="recorded-result"><CircleCheck size={14}/><span>{task.result.correct}/{task.result.attempted} correct · {task.result.accuracy}% · {task.result.time_spent} min · confidence {task.result.confidence}/5</span></div>}
  </div>
 </div>
}

function TimeCheckpointCard({test,subject,record}:{test:TimeFoundationTest;subject:string;record?:()=>void}){
 return <div className="time-checkpoint"><div><span>{subject.toUpperCase()} CHECKPOINT</span><Badge tone={test.cat_priority==="HIGH"?"blue":"neutral"}>{test.cat_priority} CAT PRIORITY</Badge></div><h4>{test.test_reference}</h4><strong>{test.test_reference} — {test.provider_title}</strong><small>T.I.M.E. Foundation · {test.subject} · 45 min reserved inside this block · Target ≥{test.advance_accuracy}% with confidence {test.confidence_gate}/5</small><div className="time-checkpoint-actions"><a className="material-open" href={test.url} {...externalMaterialLinkProps}>Open T.I.M.E. <ExternalLink size={13}/></a>{record&&<button type="button" className="secondary" onClick={record}>{test.last_attempt_id?"Record another attempt":"Record checkpoint result"}</button>}</div>{test.last_attempt_id&&<p><CircleCheck size={13}/>{test.accuracy}% · confidence {test.confidence}/5 · {test.outcome?.toLowerCase()}</p>}</div>
}

function TimeCheckpointResultModal({test,task,close,save}:{test:TimeFoundationTest;task?:StudyTask;close:()=>void;save:(payload:Record<string,unknown>)=>void}){
 const [attempted,setAttempted]=useState(test.attempted??10);const [correct,setCorrect]=useState(test.correct??0);
 return <Modal title={`Record ${test.test_reference}`} onClose={close}><form className="form-grid" onSubmit={event=>{event.preventDefault();save(formObject(event))}}><div className="checkpoint-modal-summary"><b>{test.provider_title}</b><span>{test.subject} · Foundation · {test.cat_priority} CAT priority</span></div><Field label="Attempt date"><input required name="attempted_on" type="date" defaultValue={task?.date||format(new Date(),"yyyy-MM-dd")}/></Field><Field label="Questions / sets attempted"><input required name="attempted" type="number" min="1" value={attempted} onChange={event=>setAttempted(Number(event.target.value))}/></Field><Field label="Correct"><input required name="correct" type="number" min="0" max={attempted} value={correct} onChange={event=>setCorrect(Number(event.target.value))}/></Field><Field label="Time spent (minutes)"><input required name="time_spent" type="number" min="0" defaultValue={test.time_spent??30}/></Field><Field label="Confidence"><select name="confidence" defaultValue={test.confidence??3}>{[1,2,3,4,5].map(value=><option value={value} key={value}>{value}/5</option>)}</select></Field><div className="result-preview"><span>Accuracy</span><strong>{completionAccuracy(attempted,correct)}%</strong></div><Field label="Analysis notes" span><textarea name="notes" placeholder="What should change before the next checkpoint?"/></Field><FormButtons close={close}/></form></Modal>
}

function CompletionModal({task,close,save}:{task:StudyTask;close:()=>void;save:(payload:Record<string,unknown>)=>void}){
 const [attempted,setAttempted]=useState(task.result?.attempted??task.target_count??0);const [correct,setCorrect]=useState(task.result?.correct??0);const accuracy=completionAccuracy(attempted,correct);
 return <Modal title={`Record result · ${task.title}`} onClose={close}><form className="form-grid" onSubmit={e=>{e.preventDefault();save(formObject(e))}}><Field label="Questions / sets attempted"><input required name="attempted" type="number" min="0" value={attempted} onChange={e=>setAttempted(Number(e.target.value))}/></Field><Field label="Correct"><input required name="correct" type="number" min="0" max={attempted} value={correct} onChange={e=>setCorrect(Number(e.target.value))}/></Field><Field label="Time spent (minutes)"><input required name="time_spent" type="number" min="0" defaultValue={task.result?.time_spent??task.duration}/></Field><Field label="Confidence"><select name="confidence" defaultValue={task.result?.confidence??3}><option value="1">1 · Very low</option><option value="2">2 · Low</option><option value="3">3 · Steady</option><option value="4">4 · High</option><option value="5">5 · Very high</option></select></Field>{task.subject==="DILR"&&<><Field label="Sets solved"><input name="dilr_sets_solved" type="number" min="0" max={attempted} defaultValue={task.result?.dilr_sets_solved??0}/></Field><Field label="Representation"><select name="dilr_representation" defaultValue={task.result?.dilr_representation??"GRID"}>{["TABLE","GRID","SLOTS","TIMELINE","NETWORK","EQUATIONS","VENN","DIAGRAM","OTHER"].map(value=><option key={value}>{value}</option>)}</select></Field><Field label="CAT selectability" span><select name="dilr_selectability" defaultValue={task.result?.dilr_selectability??"MAYBE"}><option>YES</option><option>MAYBE</option><option>NO</option></select></Field></>}{task.subject==="VARC"&&<Field label="Main error pattern" span><select name="varc_error_pattern" defaultValue={task.result?.varc_error_pattern??"OTHER"}>{["EXTREME_OPTION","SCOPE_SHIFT","UNSUPPORTED_INFERENCE","AUTHOR_VIEW_VS_EXAMPLE","CAUSE_EFFECT_REVERSAL","PARTIALLY_CORRECT","MISSED_QUALIFIER","MISREAD_QUESTION","TIME_PRESSURE","CLOSE_CALL","OTHER"].map(value=><option value={value} key={value}>{progressionLabel(value)}</option>)}</select></Field>}<div className="result-preview"><span>Accuracy</span><strong>{accuracy}%</strong></div><Field label="Reusable lesson / note" span><textarea name="notes" defaultValue={task.result?.notes??""}/></Field><FormButtons close={close}/></form></Modal>
}

function ReplaceMaterialModal({task,stage,data,close,save,add}:{task:StudyTask;stage:TaskResourceStage;data:AppData;close:()=>void;save:(payload:Record<string,unknown>)=>void;add:(payload:Record<string,unknown>)=>void}){
 const options=data.taskResourceOptions[taskStageKey(task.id,stage.stage)]||[];
 const [selected,setSelected]=useState(stage.resource_id);const [adding,setAdding]=useState(false);const [query,setQuery]=useState("");const [prefer,setPrefer]=useState(false);
 const [filters,setFilters]=useState<ResourceFilters>({subject:"",provider:"",type:"",difficulty:"",access:"",scope:"",topic:"",showUnavailable:false});
 const setFilter=(name:keyof ResourceFilters,value:string|boolean)=>setFilters(current=>({...current,[name]:value}));
 const filtered=useMemo(()=>filterResourceOptions(options,query,filters),[options,query,filters]);
 const unique=(field:"subject"|"provider"|"type"|"difficulty")=>[...new Set(options.map(option=>option[field]).filter(Boolean))].sort() as string[];
 const topics=[...new Set(options.flatMap(option=>[option.topic_slug,option.category]).filter(Boolean))].sort() as string[];
 const selectedOption=options.find(option=>option.id===selected);
 if(adding)return <Modal title={`Add ${stage.stage.toLowerCase()} material`} onClose={close} wide><form className="form-grid custom-material-form" onSubmit={event=>{event.preventDefault();add(formObject(event))}}><div className="custom-material-summary"><Library size={18}/><div><b>{task.topic} · {stage.stage}</b><span>Saved to your library, mapped to this topic and selected for this task.</span></div></div><Field label="Material name" span><input required name="title" placeholder="Example: Khan Academy — Ratios lesson"/></Field><Field label="URL"><input name="url" type="url" placeholder="https://…"/></Field><Field label="Where to find it"><input name="platform_path" placeholder="Course → Module → Lesson"/></Field><Field label="Material type"><select name="type" defaultValue="VIDEO"><option value="VIDEO">Video</option><option value="ARTICLE">Article</option><option value="COURSE">Course</option><option value="QUESTION_BANK">Question bank</option><option value="NOTES">Notes</option><option value="PDF">PDF</option><option value="OTHER">Other</option></select></Field><Field label="Access"><select name="access" defaultValue="FREE"><option value="FREE">Free / available</option><option value="SUBSCRIPTION">Subscription</option></select></Field><Field label="Difficulty"><select name="difficulty" defaultValue={task.difficulty}>{["FOUNDATION","INTERMEDIATE","CAT_LEVEL","TIMED","MIXED"].map(value=><option value={value} key={value}>{progressionLabel(value)}</option>)}</select></Field><Field label="Notes" span><textarea name="description" placeholder="What this material covers or when to use it"/></Field><p className="reschedule-preserved"><Check size={14}/> A URL or “Where to find it” instruction is required. Future {task.topic} tasks can offer this material for the {stage.stage.toLowerCase()} stage.</p><div className="form-actions"><button type="button" className="secondary" onClick={()=>setAdding(false)}>Back</button><button className="primary">Add and use material</button></div></form></Modal>;
 return <Modal title={`Replace ${stage.stage.toLowerCase()} material`} onClose={close} wide><div className="resource-picker"><div className="resource-picker-context"><div><span>{task.subject} · {task.topic}</span><strong>{stage.stage} resource catalogue</strong></div><small>{filtered.length} of {options.length} resources shown</small></div><div className="resource-picker-search"><Search size={18}/><input autoFocus value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search title, provider, test reference, topic, category or tags…"/>{query&&<button type="button" aria-label="Clear search" onClick={()=>setQuery("")}><X size={15}/></button>}</div><div className="resource-picker-filters"><select aria-label="Subject" value={filters.subject} onChange={event=>setFilter("subject",event.target.value)}><option value="">All subjects</option>{unique("subject").map(value=><option key={value}>{value}</option>)}</select><select aria-label="Topic" value={filters.topic} onChange={event=>setFilter("topic",event.target.value)}><option value="">All topics</option>{topics.map(value=><option key={value}>{progressionLabel(value)}</option>)}</select><select aria-label="Provider" value={filters.provider} onChange={event=>setFilter("provider",event.target.value)}><option value="">All providers</option>{unique("provider").map(value=><option key={value}>{value}</option>)}</select><select aria-label="Resource type" value={filters.type} onChange={event=>setFilter("type",event.target.value)}><option value="">All types</option>{unique("type").map(value=><option key={value}>{progressionLabel(value)}</option>)}</select><select aria-label="Level" value={filters.difficulty} onChange={event=>setFilter("difficulty",event.target.value)}><option value="">All levels</option>{unique("difficulty").map(value=><option key={value}>{progressionLabel(value)}</option>)}</select><select aria-label="Access" value={filters.access} onChange={event=>setFilter("access",event.target.value)}><option value="">Free + paid</option><option value="FREE">Free</option><option value="PAID">Paid / subscription</option></select><select aria-label="CAT scope" value={filters.scope} onChange={event=>setFilter("scope",event.target.value)}><option value="">CAT core + optional</option><option value="CORE">CAT core</option><option value="OPTIONAL">OMET optional</option></select><label className="show-unavailable"><input type="checkbox" checked={filters.showUnavailable} onChange={event=>setFilter("showUnavailable",event.target.checked)}/> Show unavailable resources</label></div><div className="resource-picker-results">{filtered.map(option=><label className={`resource-choice ${selected===option.id?"selected":""} ${!option.available?"unavailable":""}`} key={option.id}><input type="radio" name="replacement" value={option.id} disabled={!option.available} checked={selected===option.id} onChange={()=>setSelected(option.id)}/><div className="resource-choice-body"><div className="resource-choice-top"><span>{option.test_reference||option.provider}</span><div>{option.recommended&&<Badge tone="blue">RECOMMENDED</Badge>}{option.current&&<Badge tone="purple">CURRENT</Badge>}<Badge tone={option.available?"green":"neutral"}>{option.available?"AVAILABLE":"UNAVAILABLE"}</Badge></div></div><h3>{option.title}</h3><p>{option.provider_title||option.provider} · {option.subject} · {progressionLabel(option.type)}{option.difficulty?` · ${progressionLabel(option.difficulty)}`:""}</p>{(option.topic_slug||option.category)&&<small>Topic: {progressionLabel(option.topic_slug||option.category||"")}</small>}<div className="resource-choice-meta"><span>{option.cat_core?"CAT Core":"OMET / Optional"}</span>{option.cat_priority&&<span>CAT Priority: {progressionLabel(option.cat_priority)}</span>}<span>{option.free?"Free":option.subscription_name||"Subscription"}</span></div>{option.platform_path&&<small className="resource-path">{option.platform_path}</small>}</div><span className="resource-select-label">{!option.available?"Enable in Settings":selected===option.id?"Selected":"Select"}</span></label>)}{!filtered.length&&<Empty title="No matching resources" text={filters.showUnavailable?"Clear a filter or try another term.":"Try another term or show unavailable resources."}/>}</div><button type="button" className="add-custom-material" onClick={()=>setAdding(true)}><Plus size={15}/><span><b>Add new study material</b><small>Save a link or platform location and use it now</small></span><ChevronRight size={15}/></button><div className="resource-picker-footer"><label className="preference-check"><input type="checkbox" checked={prefer} onChange={event=>setPrefer(event.target.checked)}/><span><b>Prefer this source for {task.topic} in future</b><small>Optional. Leaving this off changes only this task.</small></span></label><div className="replace-actions"><button className="secondary" onClick={close}>Cancel</button><button className="primary" disabled={!selectedOption?.available} onClick={()=>save({resource_id:selected,prefer_for_topic:prefer})}>Use this material</button></div></div></div></Modal>
}

function RescheduleTaskModal({task,tasks,close,save}:{task:StudyTask;tasks:StudyTask[];close:()=>void;save:(payload:Record<string,unknown>)=>void}){
 const onMockDay=!task.manual&&task.kind==="mock"&&tasks.some(item=>item.date===task.date&&item.kind==="mock"&&!item.manual);
 const moving=onMockDay?tasks.filter(item=>item.date===task.date&&!item.completed&&!item.manual&&["mock","analysis","revision"].includes(item.kind)).sort((a,b)=>a.start_time.localeCompare(b.start_time)):[task];
 const [targetDate,setTargetDate]=useState(format(addDays(parseISO(task.date),1),"yyyy-MM-dd"));
 const firstStart=moving[0]?.start_time||task.start_time;
 const minuteOf=(value:string)=>{const [hour,minute]=value.split(":").map(Number);return hour*60+minute};
 const movingSpan=Math.max(...moving.map(item=>minuteOf(item.start_time)-minuteOf(firstStart)+item.duration));
 const latestStart=1440-movingSpan;const maxStart=`${String(Math.floor(latestStart/60)).padStart(2,"0")}:${String(latestStart%60).padStart(2,"0")}`;
 const target=tasks.filter(item=>item.date===targetDate&&!moving.some(moved=>moved.id===item.id));
 const movingMinutes=moving.reduce((sum,item)=>sum+item.duration,0);
 const targetMinutes=target.reduce((sum,item)=>sum+item.duration,0);
 return <Modal title={onMockDay?"Move mock-day plan":"Move study task"} onClose={close}>
  <form className="form-grid reschedule-form" onSubmit={event=>{event.preventDefault();save(formObject(event))}}>
   <div className="reschedule-summary"><CalendarDays size={19}/><div><strong>{onMockDay?`${moving.length} linked mock blocks`:task.title}</strong><span>{movingMinutes} minutes · currently {format(parseISO(task.date),"EEE, MMM d")}</span></div></div>
   <Field label="Move to date"><input required name="date" type="date" value={targetDate} onChange={event=>setTargetDate(event.target.value)}/></Field>
   <Field label={onMockDay?"Mock bundle starts":"Start time"}><input required name="start_time" type="time" max={maxStart} defaultValue={firstStart}/></Field>
   {onMockDay&&<div className="reschedule-note"><strong>The full mock plan moves together.</strong><span>Mock, analysis and revision keep their order and spacing. This avoids splitting a mock from its feedback work.</span></div>}
   <div className={`reschedule-load ${targetMinutes?"has-load":""}`}><span>Target-day load</span><strong>{target.length} existing blocks · {targetMinutes} min</strong><small>After moving: {targetMinutes+movingMinutes} min. Overlaps are allowed so you can choose the exact start time.</small></div>
   <p className="reschedule-preserved"><Check size={14}/> Attached materials, Replace Material choices, targets and manual overrides stay unchanged. The moved work is protected from automatic reassignment.</p>
   <FormButtons close={close}/>
  </form>
 </Modal>
}

function FocusPlan({tasks,close,complete,checkpoint}:{tasks:StudyTask[];close:()=>void;complete:(task:StudyTask)=>void;checkpoint:(task:StudyTask)=>void}){
 const steps=tasks.flatMap<{task:StudyTask;stage:TaskResourceStage|null}>(task=>task.resource_stages.length?task.resource_stages.map(stage=>({task,stage})):[{task,stage:null}]);const firstOpen=steps.findIndex(step=>!step.task.completed);const [index,setIndex]=useState(Math.max(0,firstOpen));const [running,setRunning]=useState(false);const [seconds,setSeconds]=useState(0);const [opened,setOpened]=useState(false);const entry=steps[index];const task=entry?.task;const stage=entry?.stage;
 useEffect(()=>{if(!running)return;const interval=window.setInterval(()=>setSeconds(value=>value+1),1000);return()=>window.clearInterval(interval)},[running]);
 useEffect(()=>{setSeconds(0);setOpened(false);setRunning(false)},[index]);
 if(!task)return <div className="focus-shell"><Card><Empty title="No blocks tonight" text="Return to Today to add a task."/><button className="secondary" onClick={close}>Back to Today</button></Card></div>;
 const minute=String(Math.floor(seconds/60)).padStart(2,"0");const second=String(seconds%60).padStart(2,"0");const nextIsSameTask=steps[index+1]?.task.id===task.id;
 return <div className="focus-shell"><div className="focus-top"><span>TONIGHT’S PLAN · STEP {index+1} OF {steps.length}</span><button className="secondary" onClick={close}><X size={15}/> Exit focus</button></div><Card className="focus-card"><div><Badge tone={subjectTone(task.subject)}>{task.subject}</Badge><Badge>{stage?.stage||task.kind}</Badge></div><h2>{task.title}</h2><p>{task.detail}</p>{stage&&<div className="focus-material"><span>{stage.stage} · {stage.estimated_minutes} min</span><strong>{stage.provider} — {stage.title}</strong>{stage.platform_path&&<small>{stage.platform_path}</small>}{stage.url&&<a className="primary" href={stage.url} {...externalMaterialLinkProps} onClick={()=>{setOpened(true);setRunning(true)}}>Open material <ExternalLink size={15}/></a>}</div>}{task.time_foundation_test&&<TimeCheckpointCard test={task.time_foundation_test} subject={task.subject} record={()=>checkpoint(task)}/>}<div className="focus-timer"><strong>{minute}:{second}</strong><button className="secondary" onClick={()=>setRunning(value=>!value)}>{running?<Pause size={15}/>:<Play size={15}/>} {running?"Pause":"Start timer"}</button></div>{opened&&<div className="return-prompt"><b>Back from the material?</b><span>{nextIsSameTask?"Continue to the next material stage.":"Close this block by recording the result."}</span><button className="primary" onClick={()=>nextIsSameTask?setIndex(value=>value+1):complete(task)}>{nextIsSameTask?"Next material":"Record result"}</button></div>}<div className="focus-nav"><button className="secondary" disabled={index===0} onClick={()=>setIndex(value=>value-1)}>Previous</button><button className="secondary" disabled={index===steps.length-1} onClick={()=>setIndex(value=>value+1)}>Next step <ChevronRight size={14}/></button></div></Card></div>
}

function Today({data,date,changeDate,action,open,startFocused,consumeStart,highlightTask}:{data:AppData;date:string;changeDate:(d:string)=>void;action:Phase2Action;open:(m:string)=>void;startFocused:boolean;consumeStart:()=>void;highlightTask:number|null}){
 const tasks=data.tasks.filter(t=>t.date===date);const done=tasks.filter(t=>t.completed).reduce((s,t)=>s+(t.actual_duration||t.duration),0);const [completion,setCompletion]=useState<StudyTask|null>(null);const [checkpoint,setCheckpoint]=useState<StudyTask|null>(null);const [replacement,setReplacement]=useState<{task:StudyTask;stage:TaskResourceStage}|null>(null);const [rescheduling,setRescheduling]=useState<StudyTask|null>(null);const [focused,setFocused]=useState(false);
 useEffect(()=>{if(startFocused){setFocused(true);consumeStart()}},[startFocused,consumeStart]);
 useEffect(()=>{if(highlightTask)window.setTimeout(()=>document.getElementById(`task-${highlightTask}`)?.scrollIntoView({behavior:"smooth",block:"center"}),80)},[highlightTask,date]);
 if(focused)return <><FocusPlan tasks={tasks} close={()=>setFocused(false)} complete={task=>setCompletion(task)} checkpoint={task=>setCheckpoint(task)}/>{completion&&<CompletionModal task={completion} close={()=>setCompletion(null)} save={payload=>action("completeTaskWithResult",{...payload,task_id:completion.id},"Result recorded").then(()=>setCompletion(null))}/>} {checkpoint?.time_foundation_test&&<TimeCheckpointResultModal test={checkpoint.time_foundation_test} task={checkpoint} close={()=>setCheckpoint(null)} save={payload=>action("recordTimeFoundationResult",{...payload,test_id:checkpoint.time_foundation_test_id,task_id:checkpoint.id},"Foundation checkpoint recorded").then(()=>setCheckpoint(null))}/>}</>;
 return <><div className="page-head"><div><p>{format(parseISO(date),"EEEE, MMMM d, yyyy")} · {data.meta.phase}</p><h2>{tasks.some(t=>t.kind==="mock")?"Mock day — normal curriculum replaced":"Your six-hour evening block"}</h2></div><div className="head-actions"><input type="date" value={date} onChange={e=>changeDate(e.target.value)}/><button className="secondary" onClick={()=>open("task")}><Plus size={16}/> Add task</button><button className="primary" disabled={!tasks.length} onClick={()=>setFocused(true)}><Play size={16}/> Start Tonight’s Plan</button><button className="secondary" onClick={()=>open("close")}>Close day</button></div></div><div className="plan-summary"><div><Clock3/><span><strong>{Math.floor(done/60)}h {done%60}m</strong> completed</span></div><Progress value={data.meta.plannedMinutes?done/data.meta.plannedMinutes*100:0}/><span>{tasks.filter(t=>t.completed).length} of {tasks.length} blocks done</span></div><div className="today-layout"><div><Card className="plan-card"><div className="agenda">{tasks.map((task,index)=><AgendaItem key={task.id} task={task} last={index===tasks.length-1} complete={()=>setCompletion(task)} undo={()=>action("toggleTask",{id:task.id,completed:false},"Task reopened")} replace={stage=>setReplacement({task,stage})} reschedule={()=>setRescheduling(task)} checkpoint={()=>setCheckpoint(task)} highlighted={highlightTask===task.id}/>)}</div>{!tasks.length&&<Empty title="Rest or planning day" text="Add a manual task if you want to study; manual changes are never overwritten."/>}</Card></div><aside className="today-aside"><Card><span className="eyebrow">WHY THIS PLAN</span><h3>Transparent priority</h3><ol className="priority-list"><li><b>Weak foundations</b><span>importance + mastery gap</span></li><li><b>Due revisions</b><span>overdue interval + accuracy</span></li><li><b>Daily DILR / VARC</b><span>volume without backlog inflation</span></li><li><b>Test readiness</b><span>phase + next mock</span></li></ol><p className="small-note">Material is selected only from providers enabled in Settings. Replace Material never changes the adaptive topic priority.</p></Card><Card><span className="eyebrow">RETURN WORKFLOW</span><h3>Close the feedback loop</h3><ul className="diary-list"><li><span>01</span><div><b>Open exact material</b><small>The link opens in a new tab</small></div></li><li><span>02</span><div><b>Return to Northstar</b><small>Your focus timer remains here</small></div></li><li><span>03</span><div><b>Record the result</b><small>Attempted, correct, time and confidence</small></div></li></ul></Card></aside></div>{completion&&<CompletionModal task={completion} close={()=>setCompletion(null)} save={payload=>action("completeTaskWithResult",{...payload,task_id:completion.id},"Result recorded").then(()=>setCompletion(null))}/>} {checkpoint?.time_foundation_test&&<TimeCheckpointResultModal test={checkpoint.time_foundation_test} task={checkpoint} close={()=>setCheckpoint(null)} save={payload=>action("recordTimeFoundationResult",{...payload,test_id:checkpoint.time_foundation_test_id,task_id:checkpoint.id},"Foundation checkpoint recorded").then(()=>setCheckpoint(null))}/>} {replacement&&<ReplaceMaterialModal task={replacement.task} stage={replacement.stage} data={data} close={()=>setReplacement(null)} save={payload=>action("replaceTaskResource",{assignment_id:replacement.stage.assignment_id,...payload},"Material replaced").then(()=>setReplacement(null))} add={payload=>action("addCustomStudyMaterial",{...payload,assignment_id:replacement.stage.assignment_id},"Custom material added and selected").then(()=>setReplacement(null))}/>} {rescheduling&&<RescheduleTaskModal task={rescheduling} tasks={data.tasks} close={()=>setRescheduling(null)} save={payload=>action("rescheduleTask",{...payload,task_id:rescheduling.id},"Task moved").then(()=>setRescheduling(null))}/>}</>
}

function EarlyCompletionModal({task,data,close,save}:{task:StudyTask;data:AppData;close:()=>void;save:(payload:Record<string,unknown>)=>void}){
 const [scope,setScope]=useState("TASK");const [strategy,setStrategy]=useState("AUTO");
 const movable=data.tasks.filter(item=>item.id!==task.id&&!item.completed&&!item.archived&&!item.manual&&!item.locked&&!item.pinned&&!item.aimcat_schedule_id&&item.priority!=="Critical"&&["practice","revision","sectional"].includes(item.kind)&&item.completion===0&&item.actual_duration===0&&item.date<=task.date);
 const [replacement,setReplacement]=useState(String(movable.find(item=>item.date===data.meta.today)?.id||movable[0]?.id||""));
 return <Modal title={`Complete ${task.topic} early`} onClose={close}><form className="form-grid early-completion-form" onSubmit={event=>{event.preventDefault();save({task_id:task.id,completion_date:data.meta.today,completion_scope:scope,reallocation_strategy:strategy,replacement_task_id:strategy==="SPECIFIC"?Number(replacement):undefined})}}><div className="reschedule-summary"><CalendarCheck size={19}/><div><strong>Planned {format(parseISO(task.date),"EEEE, MMM d")}</strong><span>Record actual completion on {format(parseISO(data.meta.today),"EEEE, MMM d")} and preserve the original plan in history.</span></div></div><Field label="What did you complete?" span><select value={scope} onChange={event=>setScope(event.target.value)}><option value="TASK">This scheduled task only</option><option value="TOPIC">The topic’s Foundation / Intermediate work</option></select></Field><Field label="Fill the freed future slot" span><select value={strategy} onChange={event=>setStrategy(event.target.value)}><option value="AUTO">Let Northstar choose (recommended)</option><option value="TODAY">Move the best suitable task from today</option><option value="SPECIFIC">Move another pending task</option><option value="NONE">Leave the slot free</option></select></Field>{strategy==="SPECIFIC"&&<Field label="Pending task" span><select required value={replacement} onChange={event=>setReplacement(event.target.value)}>{movable.map(item=><option value={item.id} key={item.id}>{format(parseISO(item.date),"MMM d")} · {item.title} · {item.duration} min</option>)}</select></Field>}<p className="reschedule-preserved"><Check size={14}/> AIMCATs, deadlines, manual, locked, pinned, completed, started and prerequisite work are protected. Later CAT-level, timed and mixed revisions remain scheduled.</p><FormButtons close={close}/></form></Modal>
}

function Calendar({data,select,action}:{data:AppData;select:(d:string,taskId?:number)=>void;action:Phase2Action}){
 const [month,setMonth]=useState(startOfMonth(parseISO(data.meta.today)));const [query,setQuery]=useState("");const [completing,setCompleting]=useState<StudyTask|null>(null);const searchRef=useRef<HTMLInputElement>(null);const first=month.getDay();const days=getDaysInMonth(month);const cells=Array.from({length:42},(_,index)=>index-first+1);const monthKey=format(month,"yyyy-MM");const windows=data.aimcats.filter(item=>item.end_date>=`${monthKey}-01`&&item.start_date<=format(addMonths(month,1),"yyyy-MM-01"));const matches=useMemo(()=>searchCalendarTasks(data.tasks,query),[data.tasks,query]);
 useEffect(()=>{const shortcut=(event:KeyboardEvent)=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==="k"){event.preventDefault();searchRef.current?.focus()}};window.addEventListener("keydown",shortcut);return()=>window.removeEventListener("keydown",shortcut)},[]);
 let lastResultDate="";
 return <><div className="page-head"><div><p>{format(month,"MMMM yyyy")} · scheduled AIMCAT windows</p><h2>{monthKey==="2026-11"?"Final AIMCAT → 11-day CAT consolidation":"AIMCAT → Diagnose → Repair → Practise → Next AIMCAT"}</h2></div><div className="month-nav"><button className="secondary" onClick={()=>setMonth(value=>addMonths(value,-1))}>Previous</button><button className="secondary" onClick={()=>setMonth(value=>addMonths(value,1))}>Next</button></div></div><Card className="calendar-search-card"><div className="calendar-search"><Search size={18}/><input ref={searchRef} value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search topics, tests or resources…"/><kbd>⌘/Ctrl K</kbd>{query&&<button type="button" onClick={()=>setQuery("")} aria-label="Clear calendar search"><X size={15}/></button>}</div>{query&&<div className="calendar-search-results"><div className="calendar-results-summary"><strong>{matches.length} result{matches.length===1?"":"s"}</strong><span>Searches tasks, topics, providers, resources and test references</span></div>{matches.map(task=>{const showDate=task.date!==lastResultDate;lastResultDate=task.date;const stage=task.resource_stages[0];const status=task.completed_early?"Completed early":task.completed?"Complete":task.reallocated_from_date?`Reallocated from ${format(parseISO(task.reallocated_from_date),"MMM d")}`:"Planned";return <div key={task.id}>{showDate&&<h4>{format(parseISO(task.date),"EEEE, MMMM d")}</h4>}<article className="calendar-result"><button type="button" className="calendar-result-main" onClick={()=>select(task.date,task.id)}><span><Badge tone={subjectTone(task.subject)}>{task.subject}</Badge><Badge tone={task.completed?"green":"neutral"}>{status}</Badge></span><strong>{task.title}</strong><small>{task.topic} · {task.duration} min{stage?` · ${stage.provider} — ${stage.title}`:""}{task.time_foundation_test?` · ${task.time_foundation_test.test_reference}`:""}</small></button>{task.date>data.meta.today&&!task.completed&&["practice","revision","sectional"].includes(task.kind)&&!task.aimcat_schedule_id&&<button type="button" className="secondary early-complete-button" onClick={()=>setCompleting(task)}><CalendarCheck size={14}/> Mark completed now</button>}</article></div>})}{!matches.length&&<Empty title="No calendar matches" text="Try a topic, provider, resource title or test reference."/>}</div>}</Card><div className="aimcat-window-list">{windows.map(item=><div key={item.id}><AimcatStatusBadge status={item.status}/><b>{item.test_ref}</b><span>Available {formatWindow(item)} · planned {item.planned_attempt_date?format(parseISO(item.planned_attempt_date),"MMM d"):"not set"}</span></div>)}</div><Card className="calendar-card"><div className="calendar-head">{["Sun","Mon","Tue","Wed","Thu","Fri","Sat"].map(label=><b key={label}>{label}</b>)}</div><div className="calendar-grid">{cells.map((day,index)=>{if(day<1||day>days)return <div className="calendar-cell muted" key={index}/>;const d=`${monthKey}-${String(day).padStart(2,"0")}`;const tasks=data.tasks.filter(task=>task.date===d);const deadlines=data.deadlines.filter(item=>item.date===d);const windowsToday=data.aimcats.filter(item=>item.start_date<=d&&item.end_date>=d);const planned=windowsToday.find(item=>item.planned_attempt_date===d);return <button key={d} onClick={()=>select(d)} className={`calendar-cell ${d===data.meta.today?"current":""} ${windowsToday.length?"aimcat-window-day":""} ${planned?"aimcat-planned-day":""}`}><span>{day}</span><div>{windowsToday.map(item=><em className={`event aimcat ${planned?.id===item.id?"planned":""}`} key={item.id}>{item.test_ref}{planned?.id===item.id?" · PLANNED":""}</em>)}{tasks.length&&!planned?<em className="event blue">{tasks.length} study blocks</em>:null}{tasks.some(task=>task.completed_early)&&<em className="event green">Completed early</em>}{tasks.some(task=>task.reallocated_from_date)&&<em className="event purple">Reallocated work</em>}{planned&&<em className="event purple">2h mock · 3h analyse · 1h re-solve</em>}{deadlines.map(item=><em className={`event ${item.official?"red":"green"}`} key={item.id}>{item.title}</em>)}</div><small>{tasks.filter(task=>task.completed).length?`${tasks.filter(task=>task.completed).length}/${tasks.length} complete`:windowsToday[0]?.status.replaceAll("_"," ")||""}</small></button>})}</div></Card>{monthKey==="2026-11"&&<Card className="consolidation-callout"><Flag/><div><span className="eyebrow">CAT CONSOLIDATION</span><h3>November 19–29 · 11 days</h3><p>PYQs, error logs, formula revision, selected DILR, VARC strategy, test routine and sleep consistency. No automatic full mocks.</p></div></Card>}{completing&&<EarlyCompletionModal task={completing} data={data} close={()=>setCompleting(null)} save={payload=>action("completeScheduledTopicEarly",payload,"Completed early and future capacity reallocated").then(()=>setCompleting(null))}/>}</>
}

function CatOverview({data}:{data:AppData}){const phases=[{name:"Foundation",dates:"Aug 12–31",focus:"Fundamentals, diagnostic, daily DILR + VARC",active:data.meta.today<="2026-08-31"},{name:"Core syllabus + sectionals",dates:"Sep 1–27",focus:"Core Quant, timed practice, 1–2 mocks/week",active:data.meta.today>="2026-09-01"&&data.meta.today<="2026-09-27"},{name:"Test strategy",dates:"Sep 28–Oct 25",focus:"Selection, mixed practice, ~2 mocks/week",active:data.meta.today>="2026-09-28"&&data.meta.today<="2026-10-25"},{name:"Mock-heavy peak",dates:"Oct 26–Nov 15",focus:"2–3 mocks/week, deep analysis, repair",active:data.meta.today>="2026-10-26"&&data.meta.today<="2026-11-15"},{name:"Consolidate + taper",dates:"Nov 16–28",focus:"PYQs, error logs, timing, sleep",active:data.meta.today>="2026-11-16"}];return <><div className="page-head"><div><p>Preparation target: 98–99+ percentile · floor: 95</p><h2>Aspirational trajectory, never a guarantee</h2></div><Badge tone="blue">{data.meta.countdown} days remaining</Badge></div><div className="roadmap">{phases.map((p,i)=><Card className={p.active?"phase active":"phase"} key={p.name}><span>0{i+1}</span><Badge tone={p.active?"blue":"neutral"}>{p.active?"CURRENT":"PHASE"}</Badge><h3>{p.name}</h3><b>{p.dates}</b><p>{p.focus}</p></Card>)}</div><div className="two-col"><Card><SectionTitle eyebrow="MOCK TRAJECTORY" title="Performance markers"/><div className="milestones">{[["Sep 15","80–85+"],["Sep 30","85–90+"],["Oct 15","90–95+"],["Oct 31","95+ normalising"],["Nov 15","multiple 97–99+"]].map(([d,v])=><div key={d}><span>{d}</span><i/><strong>{v}</strong></div>)}</div><p className="small-note">These are directional targets, not predictions. Section stability and repeatability matter more than one peak score.</p></Card><Card><SectionTitle eyebrow="THE OPERATING LOOP" title="Performance comes from feedback"/><div className="loop">{["Learn","Solve","Test","Analyse","Fix","Retest"].map((x,i)=><div key={x}><span>{i+1}</span><b>{x}</b>{i<5&&<ChevronRight/>}</div>)}</div><div className="principle"><Target/><span><strong>Selection is a scored skill.</strong> Abandoning a bad question at the right time is a win.</span></div></Card></div></>}

function TopicTracker({subject,data,save}:{subject:string;data:AppData;save:(p:Record<string,unknown>)=>void}){
 const topics=data.topics.filter(topic=>topic.subject===subject);const areas=[...new Set(topics.map(topic=>topic.area))];const [selected,setSelected]=useState<Topic|null>(null);
 return <><div className="page-head"><div><p>{topics.length} topics · performance-driven mastery</p><h2>{subject==="DILR"?"Set structures and selection":subject==="VARC"?"Daily comprehension and option analysis":"Foundation → Intermediate → CAT Level → Timed → Mixed"}</h2></div><div className="health"><strong>{Math.round(topics.reduce((sum,topic)=>sum+topic.mastery_score,0)/Math.max(1,topics.length))}%</strong><span>mastery index</span></div></div><SubjectInsights subject={subject} data={data}/>{areas.map(area=><Card className="topic-section" key={area}><SectionTitle title={area} eyebrow={`${topics.filter(topic=>topic.area===area).length} TOPICS`}/><div className="topic-table"><div className="topic-row header"><span>Topic</span><span>Status</span><span>Confidence</span><span>Accuracy</span><span>Practice</span><span>Revision</span></div>{topics.filter(topic=>topic.area===area).map(topic=><button className="topic-row" key={topic.id} onClick={()=>setSelected(topic)}><span><b>{topic.name}</b><small>{progressionLabel(topic.progression_level)} · mastery {topic.mastery_score}%</small></span><span><Badge tone={statusTone(topic.status)}>{topic.status}</Badge></span><span><Rating value={topic.confidence}/></span><span>{topic.attempted?topic.accuracy+"%":"—"}</span><span>{topic.attempted} attempted</span><span>{topic.next_revision||"Not scheduled"}<ChevronRight size={15}/></span></button>)}</div></Card>)}{selected&&<TopicModal topic={selected} close={()=>setSelected(null)} submit={payload=>{save(payload);setSelected(null)}}/>}</>
}

function SubjectInsights({subject,data}:{subject:string;data:AppData}){
 if(subject==="DILR")return <div className="category-performance">{data.dilrPerformance.map(row=><Card key={row.topic_id}><div><Badge tone="green">{progressionLabel(row.progression_level)}</Badge><span>{row.confidence}/5 confidence</span></div><h3>{row.category}</h3><div className="category-stats"><span><b>{row.sets_attempted}</b> sets</span><span><b>{row.solve_rate}%</b> solve rate</span><span><b>{row.median_time||"—"}</b> median min</span></div>{row.primary_resource&&<a href={row.primary_resource.url||undefined} {...externalMaterialLinkProps}>{row.primary_resource.provider} · Practice another set <ExternalLink size={13}/></a>}</Card>)}</div>;
 if(subject==="VARC")return <Card className="varc-insight"><div><span className="eyebrow">LAST 50 VARC ERRORS</span><h3>{data.varcAnalysis.most_common?progressionLabel(data.varcAnalysis.most_common):"No pattern yet"}</h3><p>{data.varcAnalysis.recommendation}</p></div><div>{data.varcAnalysis.patterns.slice(0,5).map(pattern=><span key={pattern.pattern}><b>{progressionLabel(pattern.pattern)}</b>{pattern.percentage}%</span>)}</div></Card>;
 return null;
}
function Rating({value}:{value:number}){return <span className="rating">{[1,2,3,4,5].map(x=><i className={x<=value?"on":""} key={x}/>)}</span>}
function TopicModal({topic,close,submit}:{topic:Topic;close:()=>void;submit:(p:Record<string,unknown>)=>void}){return <Modal title={topic.name} onClose={close}><form onSubmit={e=>{e.preventDefault();submit(formObject(e,{id:topic.id}))}} className="form-grid"><Field label="Status"><select name="status" defaultValue={topic.status}>{["Not Started","Learning","Practising","Strong","Needs Revision"].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Confidence (1–5)"><input name="confidence" type="number" min="1" max="5" defaultValue={topic.confidence}/></Field><Field label="Questions attempted"><input name="attempted" type="number" defaultValue={topic.attempted}/></Field><Field label="Questions correct"><input name="correct" type="number" defaultValue={topic.correct}/></Field><Field label="Accuracy %"><input name="accuracy" type="number" min="0" max="100" defaultValue={topic.accuracy}/></Field><Field label="Last practised"><input name="last_practised" type="date" defaultValue={topic.last_practised||""}/></Field><Field label="Next revision" span><input name="next_revision" type="date" defaultValue={topic.next_revision||""}/></Field><FormButtons close={close}/></form></Modal>}

function Mocks({data,action,open}:{data:AppData;action:Phase2Action;open:()=>void}){
 const current=data.aimcats.filter(item=>!item.historical||item.converted_to_additional);const past=data.aimcats.filter(item=>item.historical&&!item.converted_to_additional);const latest=data.aimcatMeta.last?.result;const [planning,setPlanning]=useState<AimcatSchedule|null>(null);const [recording,setRecording]=useState<AimcatSchedule|null>(null);const [showPast,setShowPast]=useState(false);
 return <><div className="page-head"><div><p>Priority A · scheduled T.I.M.E. AIMCAT backbone</p><h2>AIMCAT → Diagnose → Repair → Practise → Next AIMCAT</h2></div><div className="head-actions"><a className="secondary" href={data.aimcatMeta.portalUrl} {...externalMaterialLinkProps}>Open T.I.M.E. portal <ExternalLink size={15}/></a><button className="secondary" onClick={open}><Plus size={16}/> Add external mock</button></div></div><div className="metric-grid four"><Metric label="Scheduled completed" value={String(current.filter(item=>item.status==="COMPLETED").length)} suffix={`/ ${current.length}`} sub="Analysis quality over raw volume"/><Metric label="Latest percentile" value={latest?String(latest.overall_percentile):"—"} sub={latest?.name||"First diagnostic — AIMCAT2714"} tone="blue"/><Metric label="D/E/F errors" value={latest?String(latest.def_errors):"—"} sub="Selection + avoidable mistakes" tone="amber"/><Metric label="Next AIMCAT" value={data.aimcatMeta.next?.test_ref||"—"} sub={data.aimcatMeta.next?`Planned ${format(parseISO(data.aimcatMeta.next.planned_attempt_date||data.aimcatMeta.next.preferred_attempt_date),"MMM d")}`:"Scheduled series complete"}/></div><Card><SectionTitle eyebrow="SCHEDULED AIMCAT" title="Official windows and lifecycle"/><div className="aimcat-table"><div className="aimcat-row header"><span>AIMCAT</span><span>Window</span><span>Planned</span><span>Score</span><span>%ile</span><span>Analysis</span><span>Status / actions</span></div>{current.map(item=><div className="aimcat-row" key={item.id}><span><b>{item.test_ref}</b><small>T.I.M.E. · FULL_MOCK</small></span><span>{formatWindow(item)}</span><span>{item.planned_attempt_date?format(parseISO(item.planned_attempt_date),"MMM d"):"—"}</span><span>{item.result?.overall_score??"—"}</span><span>{item.result?.overall_percentile??"—"}</span><span>{item.analysis_completed?"Complete":item.actual_attempt_date?"Due":"—"}</span><span><AimcatStatusBadge status={item.status}/><div className="row-actions">{!item.actual_attempt_date&&!item.skipped&&<><button onClick={()=>setPlanning(item)}>Change date</button><button onClick={()=>setRecording(item)}>Add result</button><button onClick={()=>action("skipAimcat",{schedule_id:item.id},`${item.test_ref} marked skipped`)}>Skip</button></>}{item.status==="ANALYSIS_DUE"&&<button onClick={()=>action("markAimcatAnalysis",{schedule_id:item.id,analysis_completed:true},"Analysis completed")}>Complete analysis</button>}</div></span></div>)}</div></Card><Card><SectionTitle eyebrow="AIMCAT PERFORMANCE" title="Percentiles + rolling three-AIMCAT averages"/><AimcatTrendChart trend={data.aimcatTrend}/><p className="small-note">Target trajectory—not a prediction: August baseline · mid-Sep 80–85+ emerging · end-Sep 85–90+ · mid-Oct 90–95+ · end-Oct 95+ normalising · mid-Nov multiple 97–99+ ideally.</p></Card>{data.aimcatMeta.last?.diagnosis&&<Card className="diagnosis-card"><SectionTitle eyebrow={`${data.aimcatMeta.last.test_ref} DIAGNOSIS`} title={`${data.aimcatMeta.last.diagnosis.limiting.section} is currently limiting`}/><div className="diagnosis-grid"><div><span>Score / percentile</span><b>{data.aimcatMeta.last.result?.overall_score} · {data.aimcatMeta.last.result?.overall_percentile} %ile</b></div><div><span>Accuracy</span><b>{data.aimcatMeta.last.diagnosis.accuracy}%</b></div><div><span>Selection quality</span><b>{data.aimcatMeta.last.diagnosis.selection_quality}</b></div><div><span>Easy missed</span><b>{data.aimcatMeta.last.result?.easy_missed||0}</b></div><div><span>Strongest</span><b>{data.aimcatMeta.last.diagnosis.strongest.section} · {data.aimcatMeta.last.diagnosis.strongest.percentile} %ile</b></div><div><span>Repair allocation</span><b>{data.aimcatMeta.last.diagnosis.allocation.mock_repair}% mock-derived</b></div></div><h4>Major issues</h4><ul>{data.aimcatMeta.last.diagnosis.issues.map(issue=><li key={issue}>{issue}</li>)}</ul><h4>Next cycle</h4><ul>{data.aimcatMeta.last.diagnosis.prescription.map(item=><li key={item}>{item}</li>)}</ul></Card>}<Card><SectionTitle eyebrow="PAST AIMCAT LIBRARY" title={`${past.length} historical tests · excluded from backlog`} action={<button className="link-btn" onClick={()=>setShowPast(value=>!value)}>{showPast?"Hide":"Show library"}</button>}/>{showPast&&<div className="past-aimcat-grid">{past.map(item=><div key={item.id}><div><b>{item.test_ref}</b><AimcatStatusBadge status={item.status}/></div><span>{formatWindow(item)}</span><button className="secondary" onClick={()=>setPlanning(item)}>Use as additional mock</button></div>)}</div>}<p className="small-note">Historical windows before Aug 12 never count as overdue or reduce Schedule Health.</p></Card>{planning&&<AimcatDateModal aimcat={planning} close={()=>setPlanning(null)} save={payload=>action(planning.historical?"activatePastAimcat":"planAimcat",{...payload,schedule_id:planning.id},`${planning.test_ref} planned`).then(()=>setPlanning(null))}/>} {recording&&<AimcatResultModal aimcat={recording} close={()=>setRecording(null)} save={payload=>action("recordAimcatResult",{...payload,schedule_id:recording.id},`${recording.test_ref} diagnosis created`).then(()=>setRecording(null))}/>}</>
}

function Errors({data,open}:{data:AppData;open:()=>void}){const [q,setQ]=useState("");const rows=data.errors.filter(e=>Object.values(e).join(" ").toLowerCase().includes(q.toLowerCase()));const patterns=Object.entries(data.errors.reduce((a,e)=>{a[e.error_type]=(a[e.error_type]||0)+1;return a},{} as Record<string,number>)).sort((a,b)=>b[1]-a[1]);return <><div className="page-head"><div><p>Store the transferable lesson, not the whole solution</p><h2>Searchable mistake intelligence</h2></div><button className="primary" onClick={open}><Plus size={16}/> Log error</button></div><div className="two-col narrow-right"><Card><div className="search"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search topic, rule, source…"/></div>{rows.length?<div className="error-list">{rows.map(e=><article key={e.id}><div><Badge tone={subjectTone(e.subject)}>{e.subject}</Badge><Badge>{e.error_type}</Badge><span>{e.date}</span></div><h3>{e.topic} <small>{e.source} {e.question_ref}</small></h3><div className="error-compare"><p><b>Wrong approach</b>{e.incorrect_approach}</p><p><b>Correct insight</b>{e.correct_insight}</p></div><blockquote><strong>Rule next time</strong>{e.rule_next}</blockquote></article>)}</div>:<Empty title="No matching lessons" text="Log your first important mistake. Keep it concise enough to revise in November."/>}</Card><Card><SectionTitle eyebrow="RECURRING PATTERNS" title="What keeps happening"/>{patterns.length?patterns.map(([name,n])=><div className="pattern" key={name}><span>{name}</span><b>{n}×</b><Progress value={Math.min(100,n*20)} color="red"/></div>):<p className="small-note">Patterns appear after errors are logged. VARC reasons such as scope shift and missed qualifier are grouped automatically.</p>}</Card></div></>}

function GMAT({data,open}:{data:AppData;open:()=>void}){const diag=data.deadlines.find(d=>d.title.includes("Diagnostic"));return <><div className="page-head"><div><p>Secondary track · CAT remains priority #1</p><h2>Working target: 675+</h2></div><button className="secondary" onClick={open}><Plus size={16}/> Add attempt</button></div><div className="metric-grid three"><Metric label="Official diagnostic" value={diag?format(parseISO(diag.date),"MMM d"):"Sep W1"} sub="GMAT Official Practice Exam 1" tone="blue"/><Metric label="First attempt window" value="Oct 24–31" sub="Test-centre attempt · editable"/><Metric label="Retake rule" value="Verify" sub={data.settings.gmatRetakeRule||"Use current official GMAC guidance"} tone="amber"/></div><div className="two-col"><Card><SectionTitle eyebrow="PARALLEL LOAD" title="CAT overlap, GMAT-specific gaps"/><div className="overlap"><div><span>CAT QA</span><ChevronRight/><b>Quantitative Reasoning</b></div><div><span>CAT VARC</span><ChevronRight/><b>Verbal / Reading</b></div><div><span>CAT DILR</span><ChevronRight/><b>Data Insights</b></div></div><h4 className="subhead">GMAT-specific focus</h4><div className="chip-list"><Badge tone="purple">Critical Reasoning</Badge><Badge tone="purple">Data Insights format</Badge><Badge tone="purple">Timing strategy</Badge></div></Card><Card><SectionTitle eyebrow="MONTHLY PLAN" title="Controlled intensity"/><div className="month-plan"><div><b>August</b><p>Almost entirely CAT. Achievement inventory only.</p></div><div><b>September</b><p>30 min, 3–4 days/week after official diagnostic.</p></div><div><b>October</b><p>Up to 1h on suitable non-mock days if data supports it.</p></div></div><div className="score-guide"><span><b>675+</b> Strong outcome</span><span><b>655–675</b> Evaluate with profile</span><span><b>&lt;655</b> Consider retake if upside is real</span></div><p className="small-note">Personal targets—not official ISB cutoffs.</p></Card></div></>}

function ISB({data,open}:{data:AppData;open:()=>void}){const isb=data.deadlines.filter(d=>d.category==="ISB");return <><div className="page-head"><div><p>PGP 2027–28 · Round 2 primary, Round 3 backup</p><h2>Build the application before CAT ends</h2></div><button className="primary" onClick={open}><Plus size={16}/> Capture story</button></div><div className="rounds">{isb.filter(d=>d.official).map(d=><Card key={d.id} className={d.title.includes("Round 2")?"round primary-round":"round"}><div><Badge tone={d.title.includes("Round 1")?"neutral":d.title.includes("Round 2")?"blue":"purple"}>{d.title.includes("Round 2")?"PRIMARY":d.title.includes("Round 3")?"BACKUP":"SKIP"}</Badge><span>{format(parseISO(d.date),"MMM d, yyyy")}</span></div><h3>{d.title}</h3><p>{d.note}</p></Card>)}</div><div className="two-col"><Card><SectionTitle eyebrow="ACHIEVEMENT INVENTORY" title={`${data.stories.length} of 8–10 stories captured`} action={<button className="link-btn" onClick={open}>Add story</button>}/>{data.stories.map(s=><article className="story" key={s.id}><div><h3>{s.title}</h3><Badge tone="purple">{s.tags.split(",")[0]}</Badge></div><p>{s.situation||"Situation not yet detailed."}</p><strong>{s.impact||s.usefulness}</strong></article>)}<Progress value={Math.min(100,data.stories.length/8*100)} color="purple"/></Card><Card><SectionTitle eyebrow="APPLICATION TRACK" title="Milestones alongside CAT"/><div className="checklist">{isb.filter(d=>!d.official).map(d=><div key={d.id}><span className={d.status==="Complete"?"checked":""}>{d.status==="Complete"?<Check/>:<CircleDashed/>}</span><div><b>{d.title}</b><small>{format(parseISO(d.date),"MMM d")} · {d.note}</small></div></div>)}</div></Card></div></>}

function Resources({data,action,open}:{data:AppData;action:Phase2Action;open:()=>void}){
 const [section,setSection]=useState<"library"|"time">("library");const [tag,setTag]=useState("All");const [timeTab,setTimeTab]=useState("Recommended");const [timeScope,setTimeScope]=useState<"CAT CORE"|"OMET / OPTIONAL">("CAT CORE");const [selected,setSelected]=useState<TimeFoundationTest|null>(null);const [importing,setImporting]=useState(false);const tags=["All","Mock","PYQ","Quant","DILR","VARC","GMAT","ISB"];const resourceRows=data.resources.filter(r=>tag==="All"||r.tags.includes(tag));
 const timeTabs=["Recommended","Quant","DI","LR","VARC","Advanced","AIMCAT","Optional/OMET"];
 const testRows=data.timeFoundationTests.filter(test=>{if(timeTab==="Recommended")return Boolean(test.cat_core)&&test.cat_priority==="HIGH"&&test.outcome!=="ADVANCE";if(timeTab==="Optional/OMET")return !test.cat_core;const inScope=timeScope==="CAT CORE"?Boolean(test.cat_core):!test.cat_core;if(timeTab==="Quant")return inScope&&test.subject==="QA";if(timeTab==="DI"||timeTab==="LR"||timeTab==="VARC")return inScope&&test.subject===timeTab;return false});
 return <><div className="page-head"><div><p>{section==="time"?"Exact provider references · CAT relevance first":"Buy depth before breadth"}</p><h2>{section==="time"?"T.I.M.E. test library":"Primary system + selective secondary sources"}</h2></div><div className="head-actions">{section==="time"?<button className="primary" onClick={()=>setImporting(true)}><Plus size={16}/> Import T.I.M.E. tests</button>:<button className="primary" onClick={open}><Plus size={16}/> Add resource</button>}</div></div><div className="resource-section-tabs"><button className={section==="library"?"active":""} onClick={()=>setSection("library")}>All Resources</button><button className={section==="time"?"active":""} onClick={()=>setSection("time")}>T.I.M.E.</button></div>{section==="library"?<><div className="filters">{tags.map(t=><button className={tag===t?"active":""} onClick={()=>setTag(t)} key={t}>{t}</button>)}</div><div className="resource-grid">{resourceRows.map(r=><Card className="resource" key={r.id}><div><span className="resource-icon"><Library/></span>{r.recommended?<Badge tone="blue">RECOMMENDED</Badge>:<Badge>{r.type}</Badge>}</div><h3>{r.name}</h3><p>{r.note}</p><div className="tags">{r.tags.split(",").slice(0,4).map(t=><span key={t}>{t}</span>)}</div><a href={r.url} {...externalMaterialLinkProps}>Open resource <ExternalLink size={14}/></a></Card>)}</div></>:<><div className="time-scope"><span>FILTER</span><button className={timeScope==="CAT CORE"?"active":""} onClick={()=>{setTimeScope("CAT CORE");if(timeTab==="Optional/OMET")setTimeTab("Recommended")}}>CAT CORE</button><button className={timeScope==="OMET / OPTIONAL"?"active":""} onClick={()=>{setTimeScope("OMET / OPTIONAL");setTimeTab("Optional/OMET")}}>OMET / OPTIONAL</button></div><div className="filters time-tabs">{timeTabs.map(tab=><button className={timeTab===tab?"active":""} onClick={()=>{setTimeTab(tab);if(tab==="Optional/OMET")setTimeScope("OMET / OPTIONAL")}} key={tab}>{tab}</button>)}</div>{timeTab==="Advanced"?<TimeAdvancedResources data={data}/>:timeTab==="AIMCAT"?<TimeAimcatLibrary data={data}/>:<div className="time-test-grid">{testRows.map(test=><Card className="time-test-card" key={test.id}><div><code>{test.test_reference}</code><Badge tone={test.cat_core?"blue":"neutral"}>{test.cat_core?"CAT CORE":"OMET / OPTIONAL"}</Badge></div><h3>{test.provider_title}</h3><p>{test.subject} · {progressionLabel(test.level)}</p><dl><dt>CAT Priority</dt><dd>{progressionLabel(test.cat_priority)}</dd><dt>Status</dt><dd>{test.status}</dd><dt>Accuracy</dt><dd>{test.accuracy===null?"—":`${test.accuracy}%`}</dd><dt>Last attempt</dt><dd>{test.last_attempt?format(parseISO(test.last_attempt),"MMM d, yyyy"):"—"}</dd></dl><div className="time-test-actions"><a className="secondary" href={test.url} {...externalMaterialLinkProps}>Open T.I.M.E. <ExternalLink size={13}/></a><button className="primary" onClick={()=>setSelected(test)}>Record result</button></div></Card>)}{!testRows.length&&<Card className="time-empty"><Empty title={timeTab==="VARC"?"No verified T.I.M.E. VARC references yet":"No matching tests"} text="Import more verified references when they become available; Northstar will not invent missing provider IDs."/></Card>}</div>}</>}{selected&&<TimeCheckpointResultModal test={selected} close={()=>setSelected(null)} save={payload=>action("recordTimeFoundationResult",{...payload,test_id:selected.id},`${selected.test_reference} result recorded`).then(()=>setSelected(null))}/>} {importing&&<TimeTestImportModal close={()=>setImporting(false)} save={payload=>action("importTimeFoundationTests",payload,"T.I.M.E. catalog imported").then(()=>setImporting(false))}/>}</>
}

function TimeAdvancedResources({data}:{data:AppData}){const rows=data.studyResources.filter(resource=>resource.provider==="TIME"&&resource.type==="SECTIONAL");return <div className="resource-grid">{rows.map(resource=><Card className="resource" key={resource.id}><div><span className="resource-icon"><Target/></span><Badge tone="purple">ADVANCED</Badge></div><h3>{resource.title}</h3><p>{resource.description}</p>{resource.url&&<a href={resource.url} {...externalMaterialLinkProps}>Open T.I.M.E. <ExternalLink size={14}/></a>}</Card>)}</div>}

function TimeAimcatLibrary({data}:{data:AppData}){return <Card><SectionTitle eyebrow="AIMCAT" title="Scheduled full-mock series"/><div className="aimcat-window-list">{data.aimcats.map(item=><div key={item.id}><AimcatStatusBadge status={item.status}/><b>{item.test_ref}</b><span>{formatWindow(item)}</span></div>)}</div><a className="secondary" href={data.aimcatMeta.portalUrl} {...externalMaterialLinkProps}>Open T.I.M.E. portal <ExternalLink size={13}/></a></Card>}

function TimeTestImportModal({close,save}:{close:()=>void;save:(payload:Record<string,unknown>)=>void}){const sample="Test Reference,Description,Subject\nOBQ1001821,Foundation - provider title,QA";return <Modal title="Import T.I.M.E. tests" onClose={close} wide><form className="form-grid" onSubmit={event=>{event.preventDefault();save(formObject(event))}}><div className="checkpoint-modal-summary"><b>Required columns: Test Reference, Description, Subject</b><span>Existing references are updated by Test Reference. Optional columns: Level, Category, CAT Priority, Canonical Topic Group, Canonical Topic.</span></div><Field label="CSV / pasted table" span><textarea required name="csv" className="csv-import" defaultValue={sample}/></Field><p className="reschedule-preserved"><Check size={14}/> Provider descriptions are stored exactly. Unknown acronyms remain unmapped unless you provide canonical columns.</p><FormButtons close={close}/></form></Modal>}

function Analytics({data}:{data:AppData}){return <><div className="page-head"><div><p>Rolling signals over isolated scores</p><h2>Performance, selection and consistency</h2></div><button className="secondary"><SlidersHorizontal size={16}/> Filters</button></div><div className="analytics-grid"><Card className="span-8"><SectionTitle eyebrow="AIMCAT PERFORMANCE" title="Scheduled percentiles + rolling three"/><AimcatTrendChart trend={data.aimcatTrend}/><p className="small-note">Solid lines are individual scheduled AIMCATs; dashed lines are rolling three-AIMCAT averages.</p></Card><Card className="span-4"><SectionTitle eyebrow="MASTERY" title="Section health"/>{["Quant","DILR","VARC"].map(subject=>{const topics=data.topics.filter(topic=>topic.subject===subject);const mastery=topics.reduce((sum,topic)=>sum+topic.mastery_score,0)/Math.max(1,topics.length);return <div className="section-health" key={subject}><div><b>{subject}</b><span>{Math.round(mastery)}%</span></div><Progress value={mastery} color={subject==="Quant"?"orange":subject==="DILR"?"green":"purple"}/><small>{[...topics].sort((a,b)=>a.mastery_score-b.mastery_score)[0]?.name} needs attention</small></div>})}</Card><Card className="span-7"><SectionTitle eyebrow="RESOURCE EFFECTIVENESS" title="Observed results after use"/><div className="effectiveness-table"><div><b>Provider</b><b>Tasks</b><b>Accuracy</b><b>Confidence</b></div>{data.resourceEffectiveness.map(row=><div key={row.provider}><strong>{row.provider}</strong><span>{row.tasks}</span><span>{row.average_accuracy}%</span><span>{row.average_confidence}/5</span></div>)}{!data.resourceEffectiveness.length&&<p className="small-note">Complete practice tasks to compare observed provider outcomes. This tracks correlation, not causation.</p>}</div></Card><Card className="span-5"><SectionTitle eyebrow="RESOURCE COVERAGE" title={data.resourceCoverage.valid?"All critical mappings covered":"Coverage needs attention"}/><div className="coverage-health"><CircleCheck/><strong>{data.resourceCoverage.topics_checked} topics</strong><span>{data.resourceCoverage.resources_checked} active resources checked</span></div>{data.resourceCoverage.issues.map(issue=><p className="small-note" key={issue}>{issue}</p>)}</Card><Card className="span-6"><SectionTitle eyebrow="AVOIDABLE LOSS" title="D/E/F errors and easy misses"/><ErrorChart mocks={data.mocks}/></Card><Card className="span-6"><SectionTitle eyebrow="CONSISTENCY" title="Planned vs completed hours"/><HoursChart tasks={data.tasks}/></Card></div></>}

function WeeklyReview({data}:{data:AppData}){const start=format(startOfWeek(parseISO(data.meta.today),{weekStartsOn:1}),"yyyy-MM-dd");const rows=data.tasks.filter(t=>t.date>=start&&t.date<=data.meta.today);const completed=rows.filter(t=>t.completed);const weaknesses=weakAreas(data);const latest=data.mocks.at(-1);return <><div className="page-head"><div><p>Week of {format(parseISO(start),"MMMM d")}</p><h2>Judge the feedback loop—not hours alone</h2></div><Badge tone="blue">AUTO-GENERATED</Badge></div><div className="review-score"><Card><span>Study hours</span><strong>{(completed.reduce((s,t)=>s+(t.actual_duration||t.duration),0)/60).toFixed(1)}</strong><small>of {(rows.reduce((s,t)=>s+t.duration,0)/60).toFixed(1)} planned</small></Card><Card><span>Quant questions</span><strong>{completed.filter(t=>t.subject==="Quant").reduce((s,t)=>s+t.target_count,0)}</strong><small>Mastery-weighted practice</small></Card><Card><span>DILR sets</span><strong>{completed.filter(t=>t.subject==="DILR").reduce((s,t)=>s+t.target_count,0)}</strong><small>Selection notes required</small></Card><Card><span>RC passages</span><strong>{completed.filter(t=>t.subject==="VARC").length*2}</strong><small>Wrong options reviewed</small></Card><Card><span>Mock average</span><strong>{latest?latest.overall_percentile:"—"}</strong><small>{data.mocks.length?"latest percentile":"Enter diagnostic"}</small></Card></div><div className="two-col"><Card><SectionTitle eyebrow="MAIN WEAKNESSES" title="Where marks are leaking"/><div className="weak-list large">{weaknesses.slice(0,5).map((w,i)=><div key={w.name}><span className={`rank r${i+1}`}>{i+1}</span><div><strong>{w.name}</strong><small>{w.subject} · {w.reason}</small></div></div>)}</div></Card><Card><SectionTitle eyebrow="NEXT-WEEK RECOMMENDATION" title="Change what the evidence supports"/><ul className="recommendations"><li><Check/>Keep daily 2 RC + DILR set recurrence without carrying duplicates.</li><li><Check/>Front-load {weaknesses[0]?.name||"foundational Quant"}; it has the largest mastery gap.</li><li><Check/>Take the next mock on {data.meta.nextMock}; reserve equal energy for analysis.</li><li><Check/>Clear {data.meta.revisionDue} due revisions before adding low-value enrichment.</li></ul><div className="principle"><Brain/><span><strong>Planner signal:</strong> {data.meta.behind.detail}</span></div></Card></div></>}

function Deadlines({data,save}:{data:AppData;save:(p:Record<string,unknown>)=>void}){return <><div className="page-head"><div><p>Official dates are visually locked to their source status</p><h2>CAT, GMAT and ISB milestones</h2></div><div className="legend"><Badge tone="red">OFFICIAL</Badge><Badge>PERSONAL</Badge></div></div><Card className="deadline-table"><div className="data-row header"><span>Deadline</span><span>Category</span><span>Date</span><span>Status</span><span>Note</span></div>{data.deadlines.map(d=><form className={`data-row ${d.official?"official":""}`} key={d.id} onSubmit={e=>{e.preventDefault();save(formObject(e,{id:d.id}))}}><span><input name="title" defaultValue={d.title}/>{d.official?<Badge tone="red">OFFICIAL</Badge>:<Badge>PERSONAL</Badge>}</span><span><Badge tone={subjectTone(d.category)}>{d.category}</Badge></span><span><input name="date" type="date" defaultValue={d.date}/></span><span><select name="status" defaultValue={d.status}><option>Pending</option><option>Complete</option><option>Skipped</option></select></span><span><input name="note" defaultValue={d.note}/><button className="icon-btn" title="Save"><Save size={15}/></button></span></form>)}</Card><p className="small-note">Official labels indicate seeded official information. Verify official portals before acting; the application never silently invents or changes these dates.</p></>}

function Profile({data}:{data:AppData}){const schools=[["IIM Ahmedabad","Dream"],["IIM Bangalore","Dream"],["IIM Calcutta","Dream"],["ISB","Dream"],["IIM Lucknow","Reach"],["IIM Kozhikode","Competitive"],["IIM Indore","Competitive"],["Other top IIMs","Target"]];return <><div className="profile-hero"><div className="profile-avatar">AJ</div><div><span className="eyebrow">ADMISSIONS PROFILE</span><h2>Anusha Jain</h2><p>{data.profile.undergraduate} · {data.profile.employer}</p></div><Badge tone="green">{data.meta.workMonths} completed work-ex months</Badge></div><div className="profile-grid"><Card><SectionTitle eyebrow="ACADEMICS" title="Profile snapshot"/><div className="academic"><div><span>Class X</span><strong>{data.profile.class10}</strong></div><div><span>Class XII</span><strong>{data.profile.class12}</strong></div><div><span>Undergraduate</span><strong>{data.profile.ugCgpa}</strong><small>CGPA</small></div></div><dl><dt>Academic background</dt><dd>{data.profile.schoolBackground} → Information Science / Engineering</dd><dt>Category</dt><dd>{data.profile.category}</dd><dt>Gender</dt><dd>{data.profile.gender}</dd></dl></Card><Card><SectionTitle eyebrow="WORK EXPERIENCE" title="IBM"/><div className="work-number"><strong>{data.meta.workMonths}</strong><span>completed months</span></div><p>Full-time employment from July 1, 2024 to present. Calculated dynamically as of {format(parseISO(data.meta.today),"MMMM d, yyyy")}.</p><div className="principle"><CircleCheck/><span>At least two completed years by CAT 2026; currently aligned with the stated ISB regular PGP experience requirement. Re-verify when applying.</span></div></Card></div><Card><SectionTitle eyebrow="TARGET SCHOOLS" title="A portfolio, not a promise"/><div className="school-grid">{schools.map(([s,t])=><div key={s}><Building2/><span><b>{s}</b><small>{t}</small></span><Badge tone={t==="Dream"?"purple":t==="Reach"?"amber":"blue"}>{t}</Badge></div>)}</div><p className="small-note">Tags are planning labels, not admission-likelihood claims. Admissions formulas and weights change; any criteria shown later must include year, source and verification date.</p></Card></>}

function SettingsPage({data,action}:{data:AppData;action:Phase2Action}) {
  return <>
    <form onSubmit={e=>{e.preventDefault();action("settings",formObject(e),"Settings saved")}}>
      <div className="page-head"><div><p>Manual preferences are preserved by the planner</p><h2>Study rhythm and planning controls</h2></div><button className="primary"><Save size={16}/> Save settings</button></div>
      <div className="settings-grid">
        <Card><SectionTitle eyebrow="EVENING SCHEDULE" title="6:00 PM–12:00 AM"/><div className="form-grid"><Field label="Study start"><input name="studyStart" type="time" defaultValue={data.settings.studyStart}/></Field><Field label="Daily study minutes"><input name="dailyMinutes" type="number" min="60" max="720" defaultValue={data.settings.dailyMinutes}/></Field></div><p className="small-note">The default plan is one continuous six-hour block ending at midnight.</p><div className="schedule-preview">{[["Quant","6:00–8:15"],["DILR","8:15–10:00"],["VARC","10:00–11:30"],["Review","11:30–12:00"]].map(([a,b])=><span key={a+b}><b>{a}</b>{b}</span>)}</div></Card>
        <Card><SectionTitle eyebrow="REVISION ENGINE" title="Spaced recall"/><Field label="Intervals after learning (days)"><input name="revisionIntervals" defaultValue={data.settings.revisionIntervals}/></Field><Field label="Accuracy threshold for shorter interval"><input name="accuracyThreshold" type="number" defaultValue={data.settings.accuracyThreshold}/></Field><p className="small-note">Default: +1, +3, +7, +14 and +30 days. Low accuracy pulls the next review closer.</p></Card>
        <Card><SectionTitle eyebrow="T.I.M.E." title="Foundation checkpoints + portal"/><Field label="T.I.M.E. portal URL"><input name="timePortalUrl" type="url" defaultValue={data.settings.timePortalUrl||"https://www.time4education.com/"}/></Field><div className="form-grid inline-settings"><Field label="Continue practice from %"><input name="timeFoundationContinueAccuracy" type="number" min="0" max="99" defaultValue={data.settings.timeFoundationContinueAccuracy||"70"}/></Field><Field label="Advance from %"><input name="timeFoundationAdvanceAccuracy" type="number" min="1" max="100" defaultValue={data.settings.timeFoundationAdvanceAccuracy||"85"}/></Field><Field label="Advance confidence"><input name="timeFoundationConfidence" type="number" min="1" max="5" defaultValue={data.settings.timeFoundationConfidence||"4"}/></Field><Field label="OMET in auto-plan"><select name="timeOmetAutoSchedule" defaultValue={data.settings.timeOmetAutoSchedule||"off"}><option value="off">Off · CAT core only</option><option value="on">On · allow optional</option></select></Field></div><p className="small-note">Below Continue triggers repair; between thresholds continues targeted practice; Advance also requires the confidence gate. Open T.I.M.E. uses the configured portal and never signs in.</p></Card>
        <Card><SectionTitle eyebrow="NOTIFICATIONS" title="In-app reminders"/><label className="switch-row"><span><b>Deadline alerts</b><small>Registration, GMAT and ISB milestones</small></span><input name="notifications" type="checkbox" defaultChecked={data.settings.notifications==="on"} value="on"/></label><label className="switch-row"><span><b>Revision queue</b><small>Due and overdue topic reminders</small></span><input type="checkbox" defaultChecked/></label><label className="switch-row"><span><b>AIMCAT reminders</b><small>Availability, planned attempt and analysis-due signals</small></span><input type="checkbox" defaultChecked/></label></Card>
        <Card><SectionTitle eyebrow="PLANNING SAFETY" title="Transparent automation"/><ul className="recommendations compact"><li><Check/>Manual tasks are never overwritten.</li><li><Check/>Mock days replace, not stack onto, standard days.</li><li><Check/>Recurring work does not create backlog explosions.</li><li><Check/>Official dates are not silently changed.</li></ul></Card>
      </div>
    </form>
    <StudyMaterialSettings access={data.resourceAccess}/>
    <MyStudyMaterials data={data} action={action}/>
  </>
}

function StudyMaterialSettings({access}:{access:AppData["resourceAccess"]}) {
  const [providers,setProviders]=useState(access);
  const [saving,setSaving]=useState("");
  async function toggle(resource_provider:string, enabled:boolean) {
    setSaving(resource_provider);
    const response=await fetch("/api/app",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"setResourceAccess",payload:{resource_provider,enabled}})});
    if(response.ok) setProviders(rows=>rows.map(row=>row.resource_provider===resource_provider?{...row,enabled:enabled?1:0}:row));
    setSaving("");
  }
  const free=new Set(["RODHA","2IIM","CAT_PYQ","GMAC","USER"]);
  const group=(isFree:boolean)=>providers.filter(row=>free.has(row.resource_provider)===isFree);
  return <Card className="material-settings">
    <SectionTitle eyebrow="STUDY MATERIAL" title="Material and subscriptions"/>
    <p className="small-note">Free sources are available by default. Paid providers remain ineligible until you explicitly enable access.</p>
    <div className="material-groups">
      <div><h3>Free / available</h3>{group(true).map(row=><MaterialToggle key={row.resource_provider} row={row} saving={saving===row.resource_provider} toggle={toggle}/>)}</div>
      <div><h3>Paid / optional</h3>{group(false).map(row=><MaterialToggle key={row.resource_provider} row={row} saving={saving===row.resource_provider} toggle={toggle}/>)}</div>
    </div>
  </Card>
}

function MaterialToggle({row,saving,toggle}:{row:AppData["resourceAccess"][number];saving:boolean;toggle:(provider:string,enabled:boolean)=>void}) {
  return <label className="switch-row material-toggle"><span><b>{row.subscription_name}</b><small>{row.notes}</small></span><span className="toggle-control">{saving&&<RotateCcw className="spin" size={13}/>}<input type="checkbox" checked={Boolean(row.enabled)} disabled={saving} onChange={event=>toggle(row.resource_provider,event.target.checked)}/></span></label>
}

function MyStudyMaterials({data,action}:{data:AppData;action:Phase2Action}) {
 const [adding,setAdding]=useState(false);const materials=data.studyResources.filter(resource=>resource.provider==="USER");
 const mappingLabel=(resourceId:string)=>{const mappings=data.topicResourceMaps.filter(mapping=>mapping.resource_id===resourceId);return mappings.map(mapping=>{const topic=data.topics.find(item=>item.id===mapping.topic_id);return `${topic?.name||"Unknown topic"} · ${mapping.purpose}`}).join(" · ")||"Current task only"};
 return <><Card className="my-material-settings"><SectionTitle eyebrow="MY STUDY MATERIALS" title="Custom material library" action={<button className="primary" onClick={()=>setAdding(true)}><Plus size={15}/> Add study material</button>}/><p className="small-note">This is the same catalog used by Replace Material. Topic and stage mappings keep each link in the relevant replacement list.</p>{materials.length?<div className="my-material-list">{materials.map(resource=><div key={resource.id}><span className="resource-icon"><BookMarked size={16}/></span><div><b>{resource.title}</b><small>{mappingLabel(resource.id)}</small><em>{resource.type} · {progressionLabel(resource.difficulty||"FOUNDATION")} · {resource.free?"Free / available":"Subscription"}</em>{resource.platform_path&&<em>{resource.platform_path}</em>}</div>{resource.url?<a href={resource.url} {...externalMaterialLinkProps}>Open <ExternalLink size={13}/></a>:<Badge>PLATFORM</Badge>}</div>)}</div>:<Empty title="No custom materials yet" text="Add one here or from a task’s Replace Material window; both places stay synchronized."/>}</Card>{adding&&<SettingsMaterialModal data={data} close={()=>setAdding(false)} save={payload=>action("addCustomStudyMaterial",payload,"Custom material added").then(()=>setAdding(false))}/>}</>
}

function SettingsMaterialModal({data,close,save}:{data:AppData;close:()=>void;save:(payload:Record<string,unknown>)=>void}) {
 const subjects=["Quant","DILR","VARC"];
 return <Modal title="Add study material" onClose={close}><form className="form-grid custom-material-form" onSubmit={event=>{event.preventDefault();save(formObject(event))}}><div className="custom-material-summary"><Library size={18}/><div><b>Add once, use in Replace Material</b><span>Choose the exact topic and stage where this material should be offered.</span></div></div><Field label="Topic" span><select required name="topic_id" defaultValue=""><option value="" disabled>Select a topic</option>{subjects.map(subject=><optgroup label={subject} key={subject}>{data.topics.filter(topic=>topic.subject===subject).map(topic=><option value={topic.id} key={topic.id}>{topic.area} · {topic.name}</option>)}</optgroup>)}</select></Field><Field label="Stage"><select name="stage" defaultValue="PRACTICE"><option value="LEARN">Learn</option><option value="PRACTICE">Practice</option><option value="PYQ">PYQ</option></select></Field><Field label="Difficulty"><select name="difficulty" defaultValue="FOUNDATION">{["FOUNDATION","INTERMEDIATE","CAT_LEVEL","TIMED","MIXED"].map(value=><option value={value} key={value}>{progressionLabel(value)}</option>)}</select></Field><Field label="Material name" span><input required name="title" placeholder="Example: Khan Academy — Ratios lesson"/></Field><Field label="URL"><input name="url" type="url" placeholder="https://…"/></Field><Field label="Where to find it"><input name="platform_path" placeholder="Course → Module → Lesson"/></Field><Field label="Material type"><select name="type" defaultValue="VIDEO"><option value="VIDEO">Video</option><option value="ARTICLE">Article</option><option value="COURSE">Course</option><option value="QUESTION_BANK">Question bank</option><option value="NOTES">Notes</option><option value="PDF">PDF</option><option value="OTHER">Other</option></select></Field><Field label="Access"><select name="access" defaultValue="FREE"><option value="FREE">Free / available</option><option value="SUBSCRIPTION">Subscription</option></select></Field><Field label="Notes" span><textarea name="description" placeholder="What this material covers or when to use it"/></Field><p className="reschedule-preserved"><Check size={14}/> A URL or platform location is required. The new material will immediately appear in matching Replace Material lists.</p><FormButtons close={close}/></form></Modal>
}

function FormModal({title,type,close,submit}:{title:string;type:string;close:()=>void;submit:(p:Record<string,unknown>)=>void}){return <Modal title={title} onClose={close} wide={type==="mock"||type==="story"}><form className="form-grid" onSubmit={e=>{e.preventDefault();submit(formObject(e))}}>{type==="mock"&&<><Field label="Date"><input required name="date" type="date" defaultValue="2026-08-13"/></Field><Field label="Provider"><input required name="provider" defaultValue="IMS"/></Field><Field label="Mock name"><input required name="name" placeholder="Diagnostic SimCAT"/></Field><Field label="Overall score"><input name="overall_score" type="number" step="0.01" defaultValue="0"/></Field><Field label="Overall percentile"><input required name="overall_percentile" type="number" step="0.01" min="0" max="100"/></Field>{["varc","dilr","qa"].map(s=><div className="form-subgrid" key={s}><h4>{s.toUpperCase()}</h4><input aria-label={`${s} score`} name={`${s}_score`} type="number" step="0.01" placeholder="Score" defaultValue="0"/><input aria-label={`${s} percentile`} name={`${s}_percentile`} type="number" step="0.01" placeholder="Percentile" defaultValue="0"/><input aria-label={`${s} attempts`} name={`${s}_attempts`} type="number" placeholder="Attempts" defaultValue="0"/><input aria-label={`${s} correct`} name={`${s}_correct`} type="number" placeholder="Correct" defaultValue="0"/></div>)}<Field label="Easy questions missed"><input name="easy_missed" type="number" defaultValue="0"/></Field><Field label="D + E + F errors"><input name="def_errors" type="number" defaultValue="0"/></Field><Field label="Top weak topics" span><input name="weak_topics" placeholder="Percentages, set selection, inference"/></Field><Field label="Strategy change for next mock" span><textarea name="strategy_next"/></Field><Field label="Notes" span><textarea name="notes"/></Field></>}{type==="error"&&<><Field label="Date"><input name="date" type="date" defaultValue={format(new Date(),"yyyy-MM-dd")}/></Field><Field label="Subject"><select name="subject"><option>Quant</option><option>DILR</option><option>VARC</option><option>Mock</option></select></Field><Field label="Topic"><input required name="topic"/></Field><Field label="Source / mock"><input name="source"/></Field><Field label="Question reference"><input name="question_ref"/></Field><Field label="Error type"><select name="error_type"><option>Conceptual gap</option><option>Calculation / reading</option><option>Poor selection / too long</option><option>Easy question missed</option><option>Extreme option</option><option>Scope shift</option><option>Unsupported inference</option><option>Missed qualifier</option><option>Time pressure</option><option>Other</option></select></Field><Field label="My incorrect approach" span><textarea required name="incorrect_approach"/></Field><Field label="Correct insight" span><textarea required name="correct_insight"/></Field><Field label="Rule for next time" span><textarea required name="rule_next"/></Field></>}{type==="resource"&&<><Field label="Name"><input required name="name"/></Field><Field label="Type"><select name="type"><option>PDF</option><option>Video</option><option>Course</option><option>Google Drive</option><option>Notes</option><option>Book</option><option>Test series</option><option>Question bank</option></select></Field><Field label="URL" span><input name="url" type="url"/></Field><Field label="Tags" span><input name="tags" placeholder="Quant,Practice,PYQ"/></Field><Field label="Note" span><textarea name="note"/></Field></>}{type==="story"&&<><Field label="Story title" span><input required name="title"/></Field><Field label="Tags" span><input name="tags" placeholder="Leadership, Initiative, Client impact"/></Field>{["situation","problem","role","actions","stakeholders","leadership","impact","challenges","outcome","learning","usefulness"].map(x=><Field label={labelize(x)} span key={x}><textarea name={x}/></Field>)}</>}{type==="close"&&<><Field label="Actual study hours"><input required name="actual_hours" type="number" step="0.25" min="0" max="12"/></Field><Field label="Energy (1–5)"><input required name="energy" type="number" min="1" max="5"/></Field><Field label="Focus (1–5)"><input required name="focus" type="number" min="1" max="5"/></Field><Field label="What went well?" span><textarea name="went_well"/></Field><Field label="What was difficult?" span><textarea name="difficult"/></Field><Field label="What should tomorrow prioritise?" span><textarea name="tomorrow"/></Field></>}{type==="task"&&<><Field label="Start time"><input required name="start_time" type="time" defaultValue="20:00"/></Field><Field label="Duration (minutes)"><input required name="duration" type="number" defaultValue="30"/></Field><Field label="Subject"><select name="subject"><option>Quant</option><option>DILR</option><option>VARC</option><option>GMAT</option><option>ISB</option><option>Admin</option></select></Field><Field label="Topic"><input name="topic"/></Field><Field label="Task title" span><input required name="title"/></Field><Field label="Instructions" span><textarea name="detail"/></Field><Field label="Resource"><input name="resource"/></Field><Field label="Target count"><input name="target_count" type="number" defaultValue="0"/></Field><Field label="Accuracy target"><input name="accuracy_target" type="number" defaultValue="0"/></Field><Field label="Priority"><select name="priority"><option>High</option><option>Medium</option><option>Low</option></select></Field></>}<FormButtons close={close}/></form></Modal>}
function FormButtons({close}:{close:()=>void}){return <div className="form-actions"><button type="button" className="secondary" onClick={close}>Cancel</button><button className="primary">Save record</button></div>}

function formObject(event:FormEvent<HTMLFormElement>,extra:Record<string,unknown>={}){const raw=Object.fromEntries(new FormData(event.currentTarget).entries());const numeric=["id","duration","target_count","accuracy_target","confidence","attempted","correct","accuracy","overall_score","overall_percentile","varc_score","varc_percentile","dilr_score","dilr_percentile","qa_score","qa_percentile","varc_attempts","dilr_attempts","qa_attempts","varc_correct","dilr_correct","qa_correct","varc_incorrect","dilr_incorrect","qa_incorrect","easy_missed","def_errors","time_waste_questions","poor_dilr_selections","guessing_errors","class_a","class_b","class_c","class_d","class_e","class_f","class_g","actual_hours","energy","focus"];for(const k of numeric)if(k in raw)raw[k]=Number(raw[k]) as never;return {...raw,...extra}}
function weakAreas(data:AppData){const topicRows=data.topics.filter(t=>t.status!=="Strong").map(t=>({name:t.name,subject:t.subject,score:(5-t.confidence)*15+Math.max(0,75-t.accuracy),reason:t.attempted?`${t.accuracy}% accuracy · confidence ${t.confidence}/5`:`not yet baselined · confidence ${t.confidence}/5`}));const errorRows=data.errors.map(e=>({name:e.topic,subject:e.subject,score:70+e.repeated*10,reason:`${e.error_type} repeated ${e.repeated}×`}));return [...topicRows,...errorRows].sort((a,b)=>b.score-a.score).filter((x,i,a)=>a.findIndex(y=>y.name===x.name)===i)}
function displayTime(time:string){const [h,m]=time.split(":").map(Number);return `${h%12||12}:${String(m).padStart(2,"0")} ${h>=12?"PM":"AM"}`}
function subjectTone(s:string){if(["Quant","CAT"].includes(s))return "orange";if(["DILR","GMAT"].includes(s))return "green";if(["VARC","ISB"].includes(s))return "purple";if(s==="Mock")return "blue";return "neutral"}
function statusTone(s:string){if(s==="Strong")return "green";if(s==="Needs Revision")return "red";if(s==="Learning")return "blue";if(s==="Practising")return "purple";return "neutral"}
function labelize(s:string){return s.charAt(0).toUpperCase()+s.slice(1).replaceAll("_"," ")}
function progressionLabel(value:string){return value.toLowerCase().split("_").map(word=>word.charAt(0).toUpperCase()+word.slice(1)).join(" ")}
